const RECIPES = [{"id":"269e56f5972280168123fec2e320669b","notion":"https://app.notion.com/p/269e56f5972280168123fec2e320669b","title":"Bolognese","intro":"En rejäl men enkel Bolognese.","plan":"","groups":[{"name":"Mirepoix, 2:1:1","items":[["2","stora eller 5 små gullökar."],["2","mellanstora morötter"],["1/2","Selleri"]]},{"name":"Resten","items":[["800g","nötfärs"],["1 burk","sardeller"],["1-2 glas","rödvin"],["1 burk","creme fraiche"],["3msk","tomatpuré"],["0,5L","kycklingbuljong (1 tärning)"],["1-2 burkar","tomater"],["2","kvistar rosmarin"],["","Några lagerblad"]]}],"method":[{"name":null,"steps":["Sätt en stekpanna och en stor kastrull på värme.","Hacka grönsakerna och löken till mirepoix. Stek samtidigt nötfärsen i omgångar för att bryna.","Fräs mirepoixen i kastrullen ca 10 min.","Lägg i sardellerna mot slutet.","Häll i rödvinet för att få alkoholen att avdunsta.","Därefter blanda ner allt ihop med mirepoixen och sist ner med örterna.","Låt sjuda/koka i 1-3 h beroende på hur mycket tid som finns.","Ta ur örterna till sist.","Smaka av med salt m.m.","Koka pastan.","Blanda sås med pasta direkt från kastrullen.","Toppa med parmesan och servera."]}],"notes":[]},{"id":"330e56f5972280d68c01ddc87c4b0bc0","notion":"https://app.notion.com/p/330e56f5972280d68c01ddc87c4b0bc0","title":"Spaghetti Carbonara","intro":"Isabella Morrones recept. Äkta carbonara utan grädde — krämig tack vare pastavatten. Snåla inte med svartpepparn.","plan":"","groups":[{"name":null,"items":[["400 g","spaghetti"],["4","äggulor"],["150 g","pancetta"],["30 g","pecorinoost, finriven"],["30 g","parmesanost, finriven (gärna lagrad minst 16 månader)"],["","Svartpeppar, nymalen"],["","Salt"]]}],"method":[{"name":null,"steps":["Skär pancettan i små bitar och stek utan fett tills krispig. Lyft upp och lägg åt sidan, låt fettet vara kvar i pannan.","Koka spaghettin ca 3 minuter kortare än anvisningen på förpackningen.","Vispa ihop äggulorna med den rivna osten och rikligt med nymalen svartpeppar i en skål.","Sätt på värmen igen på pannan med stekfettet, häll i ca 3 dl pastavatten och låt koka.","Häll av spaghettin och lägg i pannan med pancettan.","Låt koka 2–3 minuter under konstant omrörning så att stärkelsen utsöndras och det bildas en krämig sås.","När vattnet kokat in och bara någon matsked återstår, ta pannan från värmen.","Tillsätt äggsmeten och rör tills det blir krämigt.","Tillsätt lite pastavatten om det blir torrt.","Smaka av med salt och peppar."]}],"notes":[]},{"id":"306e56f5972280779e11d63be0b8bea4","notion":"https://app.notion.com/p/306e56f5972280779e11d63be0b8bea4","title":"Lasagna","intro":"BA’s. Minst 3h. Troligtvis 4h. Gärna 6h.","plan":"","groups":[{"name":"Ragù Bolognese","items":[["1kg","fläskfärs"],["0,5kg","nötfärs 20%"],["","Salt \u0026amp; peppar"],["2msk","olivolja"],["60g","pancetta"],["1st","mellanstor gullök, finhackad"],["1st","ribba stjälkselleri, finhackad"],["1st","mellanstor morot, skalad och finhackad"],["6st","klyftor vitlök, skivad"],["2msk","tomatpuré"],["2dl","rödvin"],["2st","burkar hela skalade tomater (ca 800g totalt)"],["2,5dl","kycklingbuljong"],["2,5dl","3% mjölk"]]},{"name":"Béchamel","items":[["100g","smör"],["1dl","vanligt vetemjöl (lägg till en mask för tjockare konsistens)."],["1,4L","3% mjölk"],["120g","parmesan"],["","Nypa cayenne"],["","Salt \u0026amp; Peppar"]]}],"method":[{"name":"Ragù Bolognese","steps":["Lägg all färs i en stor skål, salta och peppra rejält, blanda ordentligt. Forma 18 stora köttbullar. (Behöver inte vara perfekta, ska mosas senare).","Värm under tiden en stekpanna till medium-high. Stek köttbullarna i 2 omgångar, vänd då och då för att bryna runtom hela. Cirka 6 min per omgång. Lägg över i en annan behållare/plåt innan de ska ner i TK.","Under tiden köttbullarna bryns, kan du förbereda alla andra ingredienser till Bolognesen, hacka, häll upp osv.","Sänk sedan värmen på pannan till medium. Lägg i pancetta, blanda ofta, och stek tills lätt brynt och att det börjar bli krispigt, ca 5 min. Lägg i löken, sellerin, moroten, vitlöken och fräs tills det mjuknat, ca 6-8 min.","Lägg i tomatpurén och stek tills purén mörknat, ca 2 min. Häll i vinet och sjud tills det reducerats till en tjock sås, ca 4-5 min. Häll i tomaterna och höj värmen till medium-high. Sjud tills konsistensen tjocknat, ca 8-10 min.","Häll över allt i TK och häll i buljongen och mjölken. Sätt TK på high i minst 30 min, gärna upp till 1,5h.","När det är klart i TK så kan du mosa köttbullarna med en potatisstöt (eller ballongvisp). Smaka av med salt och peppar. Reducera över medium-låg värme om det behövs (behövdes inte sist).","I förväg: Såsen kan göras 4 dagar i förväg. Låt den i så fall svalna, täck och kyl, eller frys i 3 månader.","Do Ahead: Sauce can be made 4 days ahead; let cool, then cover and chill, or freeze up to 3 months."]},{"name":"Béchamel","steps":["Smält smöret i en stor kastrull, helst 5L. Vispa i mjölet och bryn på medium värme. Vispa ofta tills mjölet börjar dofta nötigt, ca 4 min. Vispa snabbt i mjölken och höj till medium-hög värme. Låt sjuda i ca 4 min så att den tjocknar. Sänk sedan värmen till medium-low och blanda då och då, tills slät och len, ca 10 min. Ta från värmen och vispa ner den rivna parmesanen och en nypa cayenne. Smaka av med salt och peppar.","Note: Den tjocknar mer när den svalnar.","I förväg: Béchamel kan göras 1 dag i förväg. Håll kyld, värm upp precis nog för att göra den lösare."]},{"name":"Montering","steps":["Värm ugnen till 170 C.","Smörj den stora ugnsformen (scanpan) lätt med olja.","Gör 5 lager av följande, avsluta med lite mer Béchamel än de andra lagren:\n4dl Ragù, cirka\nTäckande lager pastaplattor\n3dl Béchamel, cirka","Baka i mitten/nedre delen av ugnen tills den fått fin färg, cirka 1h.","Ta ut och låt den vila i 10 min, innan servering.","I förväg: Obakad lasagne kan monteras en månad i förväg. Kyl och täck med plast och frys in. Låt tina över natten i kylen och baka sedan som ovan."]}],"notes":[{"heading":"Notes","lines":[]},{"heading":"V1","lines":["Första gången blev den riktigt god.","Då förkokade vi pastaplattorna 3 min. Testar nästa gång utan förkok och monterar direkt.","Kokade bara 40 min i TK.","Bakades ca 50 min i ugnen."]}]},{"id":"2b6e56f5972280eda612d7a9c8dcb3f4","notion":"https://app.notion.com/p/2b6e56f5972280eda612d7a9c8dcb3f4","title":"Peposa","intro":"Långkok på Oxlägg med mycket smak.","plan":"","groups":[{"name":null,"items":[["1kg","Oxlägg eller annan detalj som passar."],["1 flaska","rött vin, appassimento tog vi."],["1msk","grovt mortlad svartpeppar."],["1msk","tomatpuré."],["6 klyftor","smashad vitlök."],["","Lite smör och olja."]]}],"method":[{"name":null,"steps":["Salta köttet ordentligt. Låt vara minst 10 min.","Sätt ugnen på 130 C.","Förbered resten av ingredienserna.","Mortla svartpepparn.","Ta fram tomatpurén, smör, olja.","Öppna vinet.","Smasha vitlöken.","Hetta upp grytan och torka av köttet.","Bryn köttet så det får fin färg.","Stäng av spisen en kort stund (1 min) och sen ner med pepparn.","Ner med tomatpurén efter att pepparn fått rosta en liten stund. Fördela tomatpurén och häll därefter i lite av vinet för att lösa upp purén.","När det har stekts på en kort stund, häll ner allt vin.","Lägg i köttet och vitlöken.","Koka upp och sätt därefter in i ugnen med lock.","Låt stå i 2h i ugnen. (Körde 3,5h andra gången och det blev nästan bättre).","Reducera därefter hela grytan på spisen i cirka 1h.","Smaka av med salt och ev sötma (socker/sirap) beroende på vinet.","Servera med polenta eller potatismos."]}],"notes":[]},{"id":"2dee56f597228097a798ed12bc8606b3","notion":"https://app.notion.com/p/2dee56f597228097a798ed12bc8606b3","title":"Romanesco Broccoli Maccheroni","intro":"Klassiskt recept från Rom. Kan göras med alla sorters broccoli.","plan":"","groups":[{"name":null,"items":[["1","medium stort huvud av romanesco broccoli."],["2-3 msk","olivolja"],["3 klyftor","vitlök"],["1","gullök"],["Ca 1 tsk","gochu caru (chili flakes)"],["1","ansjovisfilé i olja"],["","Smaka av med salt och peppar"],["320g","maccheroni pasta (eller rigatoni eller mezze maniche)"],["1-2dl","riven Parmesan"]]}],"method":[{"name":null,"steps":["Dela upp romanesco-huvudet i små buketter. (Tvätta under rinnande vatten)","Ånga romanescon i 5-10 minuter (9 min sist)","Sätt samtidigt igång en stor kastrull med vatten till pastan, glöm inte saltet.","Och samtidigt sätt en stekpanna på värmning.","Hacka gullöken och vitlöken.","Häll i pastan i vattnet (om det är ca 10 min, annars när det passar).","Fräs gullöken i olivoljan.","Blanda därefter i vitlöken, gochu garu och ansjovisfilén. Efter det fräst klart kort, så stäng av värmen och låt stå.","När allt är klart ska det bara blandas i stekpannan. Det mesta av parmesanen kan blandas i.","Servera och toppa med resten av parmesanen."]}],"notes":[{"heading":null,"lines":["(Första gången ångade vi romanesco, men nästa gång kan vi testa att koka den i saltat vatten och därefter koka pastan i samma vatten efteråt)."]}]},{"id":"2bbe56f597228038ae9de8e1305db90e","notion":"https://app.notion.com/p/2bbe56f597228038ae9de8e1305db90e","title":"Rosmarinsgryta – från Katrin","intro":"Skulle kunna kallas Stracotto di Manzo. Långkokt högrev i tomatsås med rosmarin, serveras med gnocchi. Salta gärna köttet dagen innan.","plan":"","groups":[{"name":null,"items":[["1kg","högrev"],["2 burkar","tomat (passerad, krossad eller hela i burk)."],["","En bunt färsk rosmarin"],["1","gul lök"],["1","tärning köttbuljong (upplöst i en dl vatten)"]]}],"method":[{"name":null,"steps":["Skär köttbiten i mindre bitar. Salta generöst och låt sitta i minst 10 min, gärna över natten.","Hacka rosmarinen någorlunda finhackat.","Hacka löken i centimeterstora bitar.","Lös upp buljongtärningen i kokande vatten.","Sätt ugnen på 150 C.","Sätt på en traktör/gryta till hög värme.","Torka av köttet och bryn ordentligt.","Sänk värmen något och fräs lök och sen i med rosmarinen.","Sist i med tomatburkarna och buljongen.","Få upp tempen så det kokar och sätt därefter in i ugnen med lock.","Låt stå i ugnen ca 2-3h.","Reducera eventuellt till sist, cirka 30-60 min ytterligare.","Smaka av med lite salt och eventuellt annat för balans."]}],"notes":[{"heading":null,"lines":["Servera med gnocchi. (Sist köpte jag och sen pensla med smält smör och in i ugnen högt upp vid grillen efter det kokat i 1 min). Kanske behöver 5-10 min i ugn, kika ofta."]}]},{"id":"2e6e56f597228061a00bea9388dd826d","notion":"https://app.notion.com/p/2e6e56f597228061a00bea9388dd826d","title":"Lammbolognese","intro":"","plan":"","groups":[{"name":"Först","items":[["500 g","lammfärs"],["","Olivolja till stekning"]]},{"name":"Därefter","items":[["1","gul lök"],["4","vitlöksklyftor"],["1","morot"]]},{"name":"Tillsätt","items":[["3 msk","tomatpuré"],["2 dl","rött vin"]]},{"name":"Tillsätt","items":[["1 burk","hela tomater, hackade, eller krossad tomat"],["2 dl","vatten"],["2 tsk","kinesisk ljus soja"],["1 tsk","gochu garu eller annan mild chili"],["1","kvist rosmarin eller ca 1 msk torkad"],["1 tsk","salt från start"]]},{"name":"Sist","items":[["","Smaka av med salt och socker"]]},{"name":"Tillbehör och topping","items":[["400g","spaghetti"],["150g","getost fryst"]]}],"method":[{"name":null,"steps":["Sätt TK på värmning, för att bryna köttet.","Ta fram stora matberedaren med lilla skålen (tror jag) och lägg först i vitlöksklyftorna och pulsera, sedan moroten och löken. Kör tills finhackat.","Bryn färsen på hög värme i olivolja i TK kastrullen.","Lägg sedan i mixen från matberedaren (vitlöken, löken och moroten). Låt det fräsa ett par minuter under omrörning.","Rör ner tomatpurén och sedan det röda vinet. Låt koka upp så alkoholen dunstar.","Stäng av värmen (cancel på TK, bara för att vi snart ska gå över i tryckkokning).","Tillsätt burken med tomaterna och resterande ingredienser i samma stycke ovan. Rör om väl.","Sätt på locket och starta TK på high minst 30 min, gärna 40-50 plus eventuellt natural release 10 min. Men 30 min och trycksläpp direkt går bra.","Sätt sedan på lagom värme för att reducera något, börja smaka av men vänta tills reducerad.","Lyft sist ur eventuella örtkvistar.","Koka pastan när den är avsmakad och i princip färdig.","Spara lite pastavatten, häll av, blanda sedan alltihop i en gryta eller kastrull.","Riv den frusna getosten över tallriken sist, vid servering."]}],"notes":[]},{"id":"352e56f5972280da9e0cc0e150175f4f","notion":"https://app.notion.com/p/352e56f5972280da9e0cc0e150175f4f","title":"Lammrevben med rödvin och rosmarin","intro":"Långsamt ugnsstekta lammrevben med rödvin, vitlök och rosmarin — av Lorraine Elliott (Not Quite Nigella).","plan":"","groups":[{"name":null,"items":[["1,2 kg","lammrevben"],["180 ml","rödvin"],["3","kvistar rosmarin, bara bladen"],["60 g","(½ dl) farinsocker"],["25 g","bruna ansjovisfiléer (6–8 st), hackade"],["8","vitlöksklyftor, krossade"],["2 msk","worcestershiresaus"],["2 tsk","salt"],["","Vitpeppar efter smak"]]}],"method":[{"name":null,"steps":["Blanda rödvin, farinsocker, ansjovis, vitlök, worcestershiresaus och salt i en kanna. Lägg rosmarinbladen i en mortel och stöt lätt i några sekunder för att frigöra oljorna — det ska inte bli en pasta. Rör ner i vinblandningen.","Lägg revbenen i en stor ziplock-påse med marinaden och låt stå i rumstemperatur i 1 timme (ställ i kyl om det är varmt). Värm ugnen till 160°C.","Klä en stor ugnsplåt med bakplåtspapper och lägg på revbenen. Häll 4 msk av marinaden över köttet och spara resten till glasyren. Täck med oljad folie (olja insidan så att köttet inte fastnar) och rosta i 2,5 timmar (3 timmar om revbenen sitter ihop).","När det återstår ca 10 minuter, värm upp resten av marinaden i en liten kastrull och reducera tills den blir sirapsaktig men inte för tjock.","Ta bort folien från revbenen och pensla glasyren över hela ytan. Höj ugnstemperaturen till 180°C och rosta utan folie i ytterligare 15 minuter. Smaka av med salt och vitpeppar."]}],"notes":[]},{"id":"35de56f59722801da4c0dcb7caf08234","notion":"https://app.notion.com/p/35de56f59722801da4c0dcb7caf08234","title":"Bräserat Lamm i tryckkokare med Vita Bönor och Spenat","intro":"Mört lamm på benet tillagat under tryck med rosmarin, vitlök och rödvin — serveras med krämiga vita bönor och färsk spenat. Recept från Epicurious.","plan":"","groups":[{"name":null,"items":[["30 g","olivolja, plus mer till servering"],["","Lammbog med ben i skivor (ca 700g)"],["3 g","nymalen svartpeppar"],["10 g","kosher salt, delat"],["1","liten gul lök, finhackad"],["3","vitlöksklyftor, skalade och krossade"],["60 ml","rödvin"],["4","stora kvistar rosmarin"],["475 ml","varmt vatten"],["2","burkar vita bönor, t.ex. cannellini, navybönor eller smörbönor (à ca 400 g), avrunna och sköljda"],["1","knippe stor spenat, grova stjälkar borttagna"],["30 ml","färskpressad citronsaft"],["","Citronklyftor och surdegsbröd till servering (valfritt)"]]}],"method":[{"name":null,"steps":["Häll olivoljan i Instant Pot och hetta upp på Sauté-läget på hög värme tills den skimrar. Krydda lammkotletterna runtom med peppar och 7 g salt.","Bryn lammet i två omgångar tills gyllene, ca 2 minuter per sida. Lyft upp och lägg på en tallrik.","Tillsätt lök och vitlök i den heta oljan och fräs på hög Sauté-värme under omrörning tills de doftar, 1–2 minuter.","Häll i rödvinet och koka under omrörning tills stekskorpan lossnar från botten och vinet reducerats något, 2–3 minuter.","Häll i 475 ml varmt vatten. Lägg ner kotletterna och rosmarinkvistarna i ett jämnt lager i grytan. Stäng av Sauté-läget.","Lås på locket och tillaga på högt tryck i 20 minuter, släpp sedan ut trycket manuellt.","Lyft ur lammet till en skål och kasta rosmarinstjälkarna. Sätt tillbaka Sauté-läget på hög värme och låt vätskan reducera något medan du river lammet i bitar och tar bort benen.","Rör ner lammet och bönorna i vätskan och stäng av värmen. Tillsätt spenaten och resterande 3 g salt och rör tills spenaten precis sjunkit ihop. Rör i citronsaften.","Fördela i djupa tallrikar, ringla över olivolja och servera med citronklyftor och bröd."]}],"notes":[]},{"id":"39de56f59722808a9ee6dfabc6772a2c","notion":"https://app.notion.com/p/39de56f59722808a9ee6dfabc6772a2c","title":"Napolitansk Pizza","intro":"Sommaren 2026, första pizzorna på gaveln. Recept från Lilla Napoli boken. Ska vara ett så starkt mjöl som möjligt, och någorlunda torrt, men mycket vatten för att vara pizzadeg, hög sälta i degen och långa fermenteringstider för att få det lätt att töja degen. Till skillnad från bröddeg så gör du bara vik första timmen av första fermenteringen. Så först 30 min autolys och därefter 3 vikningar med 15 min mellanrum.","plan":"","groups":[{"name":"Deg","items":[["500g","mjöl (Caputo Oro eller Pizzeria, eller limabacka vetemjöl special)."],["330g","vatten"],["50g","surdeg för rimlig jästid (3h + 3h) alternativt 15g surdeg för långa jästider (över natten och hela dagen)."],["14g","salt"]]},{"name":"Till bakning","items":[["","Semolina"],["","Mjöl"]]},{"name":"Vit bas 4st","items":[["","Creme fraiche 200g"],["","Taleggio 200g"],["","Pancetta 160g"],["","Mozzarella (maxi) 250g"],["","Vitlök 3 klyftor"]]}],"method":[],"notes":[{"heading":null,"lines":["Någon stjärna, t.ex. trombette."]}]},{"id":"3dee56f5972280f4ae36d9e175193718","notion":"https://app.notion.com/p/3dee56f5972280f4ae36d9e175193718","title":"Krämig kycklinggratäng","intro":"Kycklinggratäng med soltorkade tomater, parmesan och örter, av Tareq Taylor. 4 portioner.","plan":"","groups":[{"name":"Gratäng","items":[["8","kycklinglårfiléer, med skinn"],["","Flingsalt"],["","Svartpeppar, nymald"]]},{"name":"Sås","items":[["10","soltorkade tomater, i olja"],["1 klyfta","vitlök"],["0,5","röd chilifrukt, utan kärnor"],["1 tsk","torkad timjan"],["1 tsk","torkad oregano"],["3 dl","kycklingbuljong"],["1,5 dl","vispgrädde"],["1 dl","parmesanost, fint riven"]]},{"name":"Till servering","items":[["8","körsbärstomater"],["0,5","kruka basilika"],["4 portioner","pasta"]]}],"method":[{"name":"Förberedelser","steps":["Sätt ugnen på 180 grader varmluft och koka pastan enligt förpackningen.","Bryn kycklingen på medelvärme i cirka 5 minuter tills den fått färg runtom. Salta, peppra och lägg i en ugnsform."]},{"name":"Sås","steps":["Strimla de soltorkade tomaterna och finhacka vitlök och chili. Fräs alltihop i cirka 2 minuter tills det doftar.","Tillsätt timjan, oregano, buljong, grädde och parmesan. Låt sjuda försiktigt tills osten smält."]},{"name":"I ugnen","steps":["Skeda såsen över kycklingen och gratinera mitt i ugnen i cirka 15 minuter."]},{"name":"Servering","steps":["Halvera körsbärstomaterna och plocka basilikabladen. Fördela över gratängen och servera direkt med pastan."]}],"notes":[]},{"id":"2b6e56f59722804b9d91c7e6a5c6d4c3","notion":"https://app.notion.com/p/2b6e56f59722804b9d91c7e6a5c6d4c3","title":"Polenta","intro":"Enkel och smaksatt polenta.","plan":"","groups":[{"name":null,"items":[["7,5L","vatten"],["1","köttbuljongtärning (eller annan)"],["2dl","polenta"],["40g","smör"],["2dl","riven parmesan"],["","Salt"],["","Svartpeppar"]]}],"method":[{"name":null,"steps":["Koka upp vattnet tillsammans med buljongtärningen.","Vispa ner polentan och låt koka på låg värme i 3 minuter under omrörning.","Rör ner smör och parmesan och smaka av med salt och peppar."]}],"notes":[]},{"id":"357e56f5972280618177eb6b848968af","notion":"https://app.notion.com/p/357e56f5972280618177eb6b848968af","title":"Lentilles Saucisse","intro":"Lentilles saucisse med Morteau-korv, rökt sidfläsk och portvin. Recept av Simon Auscher.","plan":"","groups":[{"name":null,"items":[["400 g","gröna linser (Puy)"],["4","Monbéliard-korvar (eller 2 Morteau)"],["300 g","rökt sidfläsk, skuret i tärningar"],["1","purjolök, vit del"],["1","stor morot, skuren i mirepoix (små tärningar)"],["1","stjälk selleri, tärnad"],["1","rödlök, hackad"],["2 klyftor","vitlök, spetsat med 3 kryddnejlikor"],["2 kvistar","timjan"],["1","lagerblad"],["2 msk","tomatpuré"],["10 cl","rött portvin"],["1,5 liter","vatten"],["20 g","smör"],["","Salt och nymalen peppar"]]}],"method":[{"name":null,"steps":["Skiva purjolöken och rödlöken fint. Tärna moroten och sellerin till mirepoix. (Denna bas ger mycket smak, så den är viktig. Den gör att linserna kan absorbera aromer under tillagningen.)","Smält smöret i en gryta på medelvärme och tillsätt sidfläsket. Stek sakta tills det är gyllenbrunt och krispigt.","Tillsätt purjolök, morot, selleri och rödlök i grytan, tillsammans med baconet. Fräs på medelvärme i 5–7 minuter tills grönsakerna börjar få lite färg.","Rör ner tomatpurén och blanda väl så att alla ingredienser täcks.","Häll i portvinet och skrapa botten för att ta upp stekskyn. Låt reducera 2–3 minuter.","Skölj linserna i kallt vatten och tillsätt dem i grytan. Häll på vatten så det täcker generöst. Lägg i vitlöksklyftorna, timjan och lagerbladet. Koka upp, sänk sedan värmen och låt sjuda på svag värme i ca 25 minuter.","Lägg i korvarna hela, prickade med en gaffel. Täck grytan och låt sjuda ytterligare 20–25 minuter tills linserna är mjuka och korvarna genomkokta. Rätten ska likna en gryta — det ska finnas vätska kvar men det ska inte vara en soppa.","Ta upp vitlök, timjan och lagerblad. Skär korvarna i tjocka skivor och blanda med linserna. Salta och peppra efter smak.","Servera gärna med lantbröd och senap. Går utmärkt att frysa in."]}],"notes":[{"heading":null,"lines":["https://simonauscher.substack.com/p/lentilles-saucisse"]}]},{"id":"357e56f597228022aa10de6d49b6b983","notion":"https://app.notion.com/p/357e56f597228022aa10de6d49b6b983","title":"Quiche Lorraine","intro":"Klassisk fransk quiche med bacon och Gruyère. Serverar 8.","plan":"","groups":[{"name":"Mördeg","items":[["250 g","vetemjöl"],["1","äggula"],["125 g","smör, i tärningar"],["50 ml","vatten"],["","(5g salt)"]]},{"name":"Fyllning","items":[["200 ml","mjölk"],["200 ml","grädde"],["2","ägg + 1 äggula"],["200 g","rökt sidfläsk (i lardons)"],["120 g","riven Gruyère (eller liknande)"],["","Fin havssalt, nymalen svartpeppar"]]}],"method":[{"name":"Förbered mördegen","steps":["Blanda mjöl och salt. Gör en grop i mitten tillsätt tärnat smör. När degen precis börjat gå ihop, tillsätt äggulan och 50 ml vatten. Arbeta snabbt med fingertopparna tills degen precis går ihop — den ska inte bli seg eller elastisk.","Forma till en boll, platta till med handflatan och plasta in.","Kyl i 30 minuter, inplastad."]},{"name":"Fyllning","steps":["Ta bort svålen från sidfläsket och skär i små tärningar (lardons). Lägg dem i en kastrull med kallt vatten, koka upp kort och häll av väl.","Vispa ihop mjölk, grädde, ägg och äggula utan att blandningen skummar. Smaka av med salt och peppar.","Värm ugnen till 180°C.","Kavla ut degen tunt, ca 3 mm. Lägg över en kavel och lyft över till en pajform. Trimma kanterna så det blir en dekorativ kant.","Fördela bacontärningarna i pajskalet. Häll över äggblandningen och strö riven ost över. Grädda direkt i 25–30 minuter tills toppen precis börjar få färg och botten är genomgräddad.","Skär quichen vid bordet och servera varm."]}],"notes":[{"heading":null,"lines":["Finns massor av variationer av receptet, med grönsaker, kött eller fisk.","s. 280 i French cooking"]}]},{"id":"2b6e56f5972280aa937ae8caee6872d3","notion":"https://app.notion.com/p/2b6e56f5972280aa937ae8caee6872d3","title":"Pumpasoppa","intro":"Krämig och mild soppa på butternutpumpa.","plan":"10 min (skala och skära) + 5 min (fräsa) + 15 min (koka) + 5 min (mixa, tillsätta grädde och smaka av)\nTotal: ca 35 min","groups":[{"name":null,"items":[["500g","skalad och urkärnad butternutpumpa"],["1","citron"],["2","schalottenlökar"],["","Grönsaksfond (1 tärning + 5dl vatten)"],["2,5dl","matlagningsgrädde"],["1","klyfta vitlök"],["","Smör"],["","Salt och peppar"]]}],"method":[{"name":null,"steps":["Skala lök och vitlök. Skär lök och pumpa i bitar. Finhacka vitlöken. Cirka 10 minuter.","Fräs pumpa, lök och vitlök i smöret i en kastrull på låg värme i ca 5 minuter.","Tillsätt fond och vattnet och koka på svag värme under lock ca 15 minuter. Mixa soppan slät med stavmixer. Tillsätt grädden och koka upp. Smaka av med salt, peppar och citronjuice, cirka 5 minuter.","Toppa soppan med olja och peppar. Servera med gärna med surdegsfrallor."]}],"notes":[]},{"id":"28ce56f5972280e288ddef22c9eacae8","notion":"https://app.notion.com/p/28ce56f5972280e288ddef22c9eacae8","title":"Sallad (Arket)","intro":"En grundläggande sallad med enkla komponenter men ändå komplett. Middag, kan vara lunch eller matlådor.","plan":"","groups":[{"name":"Basen","items":[["Ca 150g","torra baljväxter (linser / ärtor)"],["1dl","torr quinoa eller liknande (bulgur, korn, ris)"]]},{"name":"Grönsaker m.m. (välj ut ett antal passande)","items":[["1","äpple/päron med sötma och syra, skivat/tärnat"],["","Lagom mängd bladgrönt (babyspenat)"],["","Ugnsrostade morötter / pumpa / aubergine"],["1","tunt skivad rödlök (blötlagd)"],["","Finstrimlad kål"],["","Picklad rödlök / Surkål"]]},{"name":"Toppings","items":[["1-2","paket fetaost"],["Ca 1dl","rostade nötter / solrosfrön"]]},{"name":"Dressing","items":[["4 msk","olivolja eller kallpressad rapsolja"],["3 msk","äppelcidervinäger"],["3 tsk","honung"],["","En nypa salt"],["","Hackad persilja"],["1","finhackad schalottenlök"]]}],"method":[{"name":null,"steps":["Se till så baljväxt är kokad och svalnad","Sätt på ugnen på ca 200 C","Rör ihop dressingen","Blanda dressingen med baljväxt för att marinera","Förbered grönsak till rostning, sätt in i ugnen.","Förbered grönsaker: skiva rödlök och äpple och lägg ihop med bladgrönt","Blanda då med marinerad baljväxt","Toppa med fetaost och rostade nötter/frön.","Smaka av och justera med citron/vinäger och salt"]}],"notes":[]},{"id":"2dbe56f59722803380fdfb70a2ab49a0","notion":"https://app.notion.com/p/2dbe56f59722803380fdfb70a2ab49a0","title":"Grönkålspaj med chèvre","intro":"Mustig paj med grönkål, rödlök, mozzarella, chèvre och valnötter i krämig äggstanning.","plan":"10 min (pajdeg) + 15 min (kylvila, grönkålen fräses under tiden) + 10 min (förgrädda skalet, stanning görs under tiden) + 30–35 min (grädda) + 20–30 min (svalna)\nTotal: ca 1,5 h","groups":[{"name":"Pajdeg","items":[["3dl","vetemjöl"],["125g","smör"],["0,5tsk","salt"],["4msk","vatten"]]},{"name":"Fyllning","items":[["1L/200g","grönkål, färsk, strimlad, utan stam."],["1/2","rödlök"],["1msk","olivolja"],["2krm","salt"],["100g","mozzarella, riven isär"],["100-200g","chèvre"],["50g","valnötter"]]},{"name":"Äggstanning","items":[["4st","ägg"],["2dl","grädde"],["0,5tsk","salt"],["0,5dl","vatten"]]}],"method":[{"name":"Pajdeg","steps":["Ta fram bunken till köksassistenten. Skär smöret i små kuber och lägg i bunken med mjöl och salt samt vatten. Arbeta hastigt ihop till en pajdeg med mördegsvisparna.","Täck över degen och ställ i kylen en kvart. Gärna lite längre.","När du ställt degen på kylning kan du sätta på ugnen på 225 C varmluft."]},{"name":"Resten","steps":["Skölj och repa grönkålen. Lägg därefter i matberedare och finhacka.\n(Fryst kan användas, då rakt i matberedaren, efter något upptinad).","Skala och hacka rödlök. Fräs i några minuter i olivoljan.","Tillsätt grönkålen och låt steka på låg värme tills den mjuknat samt tappat all vätska. Salta. Rör då och då. Sätt åt sidan att svalna.","Ta fram pajdegen igen och tryck ut den i en pajform. (Kanske kan lära mig kavla ut och trimma kanterna..) Stick hål med en gaffel i pajdegen här och där.","Grädda pajskalet i 10 minuter i nedre delen av ugnen.","Blanda under tiden ägg med grädde samt vatten i en bunke till äggstanning.","Skiva chevre i ca 0,5cm tunna skivor.","Ta sedan ut pajskalet igen och:\n- Sprid ut grönkålen på botten av pajdegen.\n- Riv och lägg mozzarella över grönkålen.\n- Häll över äggstanningen.\n- Sprid ut chèvre skivorna på toppen.\n- Fördela valnötterna.","Sänk värmen till 180 C.","Grädda grönkålspajen i nedre delen av ugnen ca 30-35 minuter eller tills pajen fått fin färg och äggstanningen stelnat. Passa den under tiden och börjar den brännas på kanterna mot slutet så kan du sänka värmen till 175 grader samt lägg över lite bakplåtspapper eller folie.","Ta ut och låt pajen svalna något innan servering. Gärna cirka 20-30 min."]}],"notes":[{"heading":null,"lines":["Servera gärna med en enkel sallad med dijondressing."]}]},{"id":"303e56f5972280e482e9fe3c94921d4a","notion":"https://app.notion.com/p/303e56f5972280e482e9fe3c94921d4a","title":"Pumpaplåt","intro":"Ugnsrostad butternutpumpa med chorizo och grönkål, serverad med quinoa, rostade pumpafrön och fetaost.","plan":"15 min (skala och skära pumpan) + 15 min (i ugnen) + 10 min (med grönkålen, quinoan kokar under tiden) + 5 min (toppa)\nTotal: ca 45 min","groups":[{"name":null,"items":[["1,5 kg","butternutpumpa"],["4","vitlöksklyftor"],["0,5 dl","olivolja"],["1 tsk","salt"],["0,5 tsk","svartpeppar"],["400 g","färsk chorizo"],["200 g","färsk grönkål"],["1 - 2 msk","olivolja"],["1 dl","rostade pumpafrön"],["150 g","fetaost"],["2 dl","quinoa"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 200 C.","Skala pumpan (med kniv eller skalare, kan skära i ciklar först för att lättare skala med skalare). Dela på mitten och skrapa ur kärnorna. Skär pumpan i små klyftor och lägg på en bakpappersklädd plåt. Krossa vitlöksklyftorna. Blanda pumpan med vitlök, 1/2 dl olja, salt och peppar.","Skiva chorizon och lägg på plåten. Ställ in i mitten av ugnen ca 15 minuter.\nRiv grönkålen i mindre bitar. Massera grönkålen med 1–2 msk olja. Ta ut plåten och lägg på grönkålen. Ställ in ytterligare 10 minuter.","Koka nu quinoan. 2dl quinoa till 4dl vatten, med lite salt. Koka först upp vattnet, häll därefter i quinoan och ha på svag värme i 10 min, därefter vila i fem min med lock. Fluffa sedan.","Rosta pumpafrön under tiden quinoan kokar.","Toppa pumpaplåten med nötter och smulad fetaost."]}],"notes":[]},{"id":"357e56f59722802e9eb5e37932f5d9ba","notion":"https://app.notion.com/p/357e56f59722802e9eb5e37932f5d9ba","title":"Potatis och purjolökssoppa","intro":"Enkel och smakrik soppa av Fredrik. 4 portioner.","plan":"10 min (skölja och hacka purjolök, skala och tärna potatis) + 5 min (fräsa och koka upp) + 10–15 min (sjuda) + 5 min (grädde och smaka av)\nTotal: ca 35 min","groups":[{"name":null,"items":[["1","purjolök"],["1 msk","olivolja eller matolja"],["8 dl","vatten"],["6–8","fasta potatisar (ca 600 g)"],["2 msk","grönsaksfond eller 2 grönsaksbuljongtärningar"],["2,5 dl","matlagningsgrädde"],["1 tsk","torkad timjan"],["","Salt och nymalen svartpeppar"],["","Ev. färsk timjan till dekoration"]]}],"method":[{"name":null,"steps":["Dela purjolöken längs med på mitten och skölj noga. Dela en gång till och hacka fint.","Skala potatisen och skär i kuber på ca 1×1 cm. Steg 1–2 tar cirka 10 minuter.","Fräs purjolöken i oljan i en stor kastrull. Tillsätt vatten, potatis, fond och timjan. Cirka 5 minuter.","Låt koka upp och sjuda på medelvärme ca 10–15 minuter tills potatisen är mjuk.","Tillsätt grädden och koka upp. Smaka av med salt och svartpeppar — det är gott med lite sting! Cirka 5 minuter."]}],"notes":[{"heading":null,"lines":["https://fredriksfika.allas.se/fredriks-middagstips/potatis-och-purjolokssoppa/"]}]},{"id":"35de56f5972280f4b99feb32f6571391","notion":"https://app.notion.com/p/35de56f5972280f4b99feb32f6571391","title":"Nötfärsbiffar med getost, tzatziki och rostade rotfrukter","intro":"Saftiga nötfärsbiffar med getost och rostad lök, serverade med timjanrostade rotfrukter och hemgjord tzatziki. Recept av Gustav Trägårdh via Tasteline.","plan":"","groups":[{"name":"Rotfrukter","items":[["200 g","potatis"],["250 g","palsternacka"],["500 g","morot"],["30 ml","olivolja"],["2 tsk","torkad timjan"],["","Salt och svartpeppar"]]},{"name":"Färsbiffar","items":[["500 g","nötfärs"],["1,5 tsk","salt"],["50 g","rostad lök"],["120 g","getost, smulad"],["100 ml","crème fraîche"],["1","vitlöksklyfta, riven"],["","Skal av ½ citron"],["½","röd chilipeppar, finhackad"]]},{"name":"Stekning","items":[["7 ml","olivolja"],["7 g","smör"],["","Persilja att toppa med"]]},{"name":"Tzatziki","items":[["½","gurka"],["200 ml","matyoghurt"],["30 ml","olivolja"],["","Salt och svartpeppar"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 200°C. Skala och skär rotfrukterna i grova bitar. Vänd på en plåt med olivolja, timjan, salt och peppar. Rosta i ugnen ca 30 minuter.","Blanda nötfärsen med salt, rostad lök, smulad getost, crème fraîche, riven vitlök, citronskal och finhackad chili. Blanda väl och forma 8 biffar.","Hetta upp olja och smör i en stekpanna på medelhög värme. Stek biffarna ca 2–3 minuter per sida tills gyllene. Sänk värmen och låt dem bli klara i pannan.","Riv gurkan och krama ur vätskan ordentligt. Blanda med yoghurt, salt och peppar. Ringla över olivoljan.","Servera färsbiffarna med rostade rotfrukter och tzatziki."]}],"notes":[]},{"id":"367e56f5972280eba358cd39e9236933","notion":"https://app.notion.com/p/367e56f5972280eba358cd39e9236933","title":"Kycklingcurry med äpple","intro":"Krämig kycklingcurry med lök och små bitar av äpple. Recept från Katrin.","plan":"","groups":[{"name":null,"items":[["Ca 500 g","kycklingfilé, tärnad"],["1","gul lök, grovhackad"],["1–2","vitlöksklyftor, hackade"],["1–2 msk","gul curry"],["1 msk","vetemjöl"],["3 dl","grädde, mjölk eller crème fraiche"],["1–2","äpplen, skalade och tärnade i ca 1 cm bitar"],["","Salt och peppar"],["","Smör till stekning"]]}],"method":[{"name":null,"steps":["Stek kycklingtärningarna färdiga i smör i en panna. Salta och peppra, lägg åt sidan.","Fräs löken, vitlöken och curryn i smör i en kastrull tills löken mjuknat.","Pudra över mjölet och blanda. Häll på grädde, mjölk eller crème fraiche under omrörning och låt sjuda till en krämig sås.","Lägg i kycklingen och äpplet och låt puttra några minuter så äpplet mjuknar något men behåller lite tuggmotstånd.","Smaka av med salt och peppar."]}],"notes":[]},{"id":"373e56f597228094ae5bcab44845df47","notion":"https://app.notion.com/p/373e56f597228094ae5bcab44845df47","title":"Dillkött med kokt potatis","intro":"Långkokt högrev smaksatt med dill, lagerblad och vitpeppar, serverad med kokt potatis och ångad broccoli. Efter Tommy Myllymäkis recept, anpassat för tryckkokare och vanligt nötkött.","plan":"Total: ca 2 h på spisen (ca 45 min i tryckkokare)","groups":[{"name":"Basen","items":[["800 g","högrev, bringa eller bog (nöt eller kalv)"],["3","morötter"],["½","purjolök"],["2","lagerblad"],["1 tsk","dillfrö"],["5","vitpepparkorn"]]},{"name":"Efter tillagning","items":[["3 dl","grädde"],["½ dl","ättiksprit 12 %"],["¾ dl","strösocker"],["","Salt"],["","Maizenaredning"],["50 g","dill"]]},{"name":"Tillbehör","items":[["800 g–1 kg","potatis"],["1","broccolihuvud"]]}],"method":[{"name":"Kött \u0026amp; sås","steps":["(Börja med potatisen om du vill att de hinner svalna)","Skär köttet i 2x2 cm tärningar. Lägg i en kastrull och häll på vatten så att det täcker.","Koka i 2 minuter och skumma av skummet som lägger sig på ytan.","Skär morötter och purjolök i 3 cm tjocka skivor och tillsätt. Lägg i lagerblad, dillfrön och vitpepparkorn.","Spisen: Låt koka på låg värme i ca 2 timmar, fyll på med vatten så att köttet hela tiden är täckt. Koka tills köttet är mört och faller sönder.","Tryckkokare: Häll på vatten precis så det täcker – fyll inte på mer. Kör under fullt tryck i 25–30 min, bringa och bog behöver mot 35 min.","Tillsätt grädden och koka upp. Smaka av med socker, ättika och salt, lite i taget till önskad smak.","Red av med maizenaredning.","Hacka dillen och rör ner den."]},{"name":"Tillbehör","steps":["Starta potatisen i god tid – skala och koka i lättsaltat vatten ca 20–25 minuter tills mjuk.","Dela broccolin i buketter och ånga 4–5 minuter tills knaprig och genomvarm.","Servera dillköttet med kokt potatis och ångad broccoli."]}],"notes":[]},{"id":"2e4e56f5972280afaa6df5604901c8b4","notion":"https://app.notion.com/p/2e4e56f5972280afaa6df5604901c8b4","title":"Laxbitar Sous Vide med fänkål","intro":"Sous vide-lax med ugnsbakad fänkål och lök, blandat med pärlcouscous och citron.","plan":"15 min (värma badet, salta och packa laxen) + 15 min (skiva lök och fänkål) + 20–30 min (fänkålen i ugnen, couscousen kokar och laxen går i badet under tiden) + 5 min (smaka av och blanda)\nTotal: ca 1 h","groups":[{"name":null,"items":[["4st","laxbitar (frysta som är tinade, men kan vara frysta)"],["1st","liten eller medium gullök"],["1st","citron"],["1st","fänkål"],["Ca 4 msk","olivolja"],["Ca 4st","vitlöksklyftor"],["4dl","pärlcouscous"],["","Salt"]]}],"method":[{"name":null,"steps":["Sätt igång värmning av sous vide bad i TK eller med stav (körde med TK sist).\n- Temperaturen 46 C är den som kändes mest intressant att testa första gången (tog dock 45 C i TK vilket kändes bra, men finns en bild med temperaturer och en tabell nedan för andra resultat än detta..","Salta laxen ordentligt och lägg i vakuumpåsar (tog två per påse sist) med en lagom stor smörbit mellan laxbitarna. Ställ åt sidan tills badet är redo.","Sätt på ugnen på 200 C.","Skiva lök tunt, gärna med mandolin. Inte tunnaste, men drygt 1mm ungefär.","Förbered fänkålen: Skär bort dillen (de övre delarna) och skär bort bottenbiten.\nSkiva sedan lika tunt som löken, eller 1-2mm tjocka skivor, med mandolinen.","Lägg sedan allt i stekpanna/ugnsform som har passande lock. (Du kan förvärma stekpannan på spisen innan ugnen).","Ringla olivolja och salta ordentligt.","Skiva sedan 3 fina skivor citron och lägg på. Sätt på locket och kör in i ugnen på minst 20 min. Kolla av och smaka av så allt är tillagat men inte överkokt och mosigt. Kan köras utan lock i 10 min till för att få lite mindre fukt.","Koka upp rikligt med vatten till pärlcouscous. Salta halvvägs till pastavatten. Sjud i 20-25 min.","När fänkålen är klar i ugnen kan du ta bort citronskivorna och smaka av med salt, olja, citronsaft och sirap/socker. Blanda till sist i pärlcouscousen (allt) och smak av igen.\n- Tillägg från sist är citronzest och mycket mer fänkålsdill eller vanlig dill.","Servera gärna med en citronsås till. Link to page (ska lägga in här)."]}],"notes":[{"heading":null,"lines":["(Not: skippa citronskivorna eller lös bitterheten först)."]},{"heading":"Sous Vide Salmon Cooking Temperatures","lines":["Texture | Temperature","Like firm sashimi | 41°C","Soft and buttery | 43°C","Translucent and starting to flake | 46°C","Very moist, tender, and flaky | 49°C","Firm, moist, and flaky | 54°C"]}]},{"id":"357e56f597228019816efe2aa6a91d93","notion":"https://app.notion.com/p/357e56f597228019816efe2aa6a91d93","title":"Kroppkakor av kokt potatis","intro":"Klassiska svenska kroppkakor gjorda på kokt mosad potatis med fyllning av rimmat fläsk och lök.","plan":"","groups":[{"name":null,"items":[["1 kg","mjölig potatis"],["","vatten och salt (till kokning av potatis)"],["1","stort ägg"],["2½–3 dl","vetemjöl"],["1 tsk","salt"]]},{"name":"Fyllning","items":[["150 g","rimmat fläsk"],["1","gul eller röd lök"],["1 krm","vitpeppar"],["½ tsk","stött eller malen kryddpeppar"]]},{"name":"Kokning","items":[["2 l","vatten"],["1 msk","salt"]]}],"method":[{"name":null,"steps":["Skala och skölj potatisen. Koka i saltat vatten tills mjuk. Häll av vattnet och ånga av.","Pressa potatisen genom purépress eller mosa med potatisstöt. Låt kallna.","Skär fläsket i små tärningar. Skala och finhacka löken. Bryn fläsket i en panna, lägg i löken och låt fräsa en stund. Krydda med peppar och låt fyllningen kallna.","Blanda mosad potatis med lätt uppvispat ägg, mjöl och salt. Rör inte för mycket.","Forma degen till en rulle och skär i ca 12 bitar. Gör en fördjupning i varje bit, lägg i en knapp matsked fyllning och tryck ihop degen till runda, lite platta bullar.","Koka upp vatten med salt. Lägg i några kroppkakor i taget och koka 10–12 minuter, eller ca 5 minuter efter att de flutit upp.","Ta upp med hålslev och servera riktigt varma med lingonsylt och smält smör. Gärna också lite sallad."]}],"notes":[]},{"id":"3bde56f59722802fa8fbf8b1059d400f","notion":"https://app.notion.com/p/3bde56f59722802fa8fbf8b1059d400f","title":"Portabellosallad","intro":"Ljummen svartrissallad med kall ugnsbakad portabello, rå morot och gulbeta, grönt äpple och en rund, ostig basilikadressing. Fyra portioner. Recept byggt utifrån Beets lunch.","plan":"","groups":[{"name":"Ugnsbakad portabello","items":[["4","stora portabellosvampar (ca 400 g)"],["2 msk","olivolja"],["1 msk","japansk soja"],["1","vitlöksklyfta"],["½ tsk","salt"]]},{"name":"Svartris","items":[["200 g","svartris"],["1 tsk","salt"],["1 msk","olivolja"]]},{"name":"Rostad palsternackskräm","items":[["500 g","palsternacka"],["1 msk","olivolja"],["1","vitlöksklyfta"],["40 g","smör, kallt och tärnat"],["½–1 dl","grädde"],["","Några droppar citronsaft"],["","Salt"]]},{"name":"Basilikadressing","items":[["30 g","färsk basilika"],["40 g","riven parmesan"],["1 dl","olivolja"],["1 msk","citronsaft"],["½ tsk","honung"],["½","vitlöksklyfta"],["","Salt"]]},{"name":"Sallad och topping","items":[["1","romansallad eller ½ isbergssallad"],["2","medelstora morötter"],["1","medelstor gulbeta"],["1","stort grönt äpple, t.ex. Granny Smith"],["100 g","linsgroddar"],["75 g","rostade saltade mandlar"],["1","citron"],["1 tsk","flingsalt"],["½ tsk","nymalen svartpeppar"]]}],"method":[{"name":"Ugnsbakad portabello","steps":["Sätt ugnen på 200°C. Borsta av svamparna och ta bort fötterna. Skär i bitar.","Blanda olivolja, soja, riven vitlök och salt. Tossa i dressingen.","Baka 20–25 minuter tills de är mjuka och glansiga. Låt svalna helt — de ska serveras kalla."]},{"name":"Svartris","steps":["Skölj riset i kallt vatten och koka i rikligt med saltat vatten i ca 40 minuter — kornen ska vara mjuka men ha kvar tuggmotstånd.","Häll av, vänd i olivoljan och låt stå ljummet. Riset ska vara varmt till ljummet vid servering, inte kallt."]},{"name":"Rostad palsternackskräm","steps":["Sätt ugnen på 200°C. Skala palsternackan och skär i jämna bitar. Vänd i olivolja och salt, lägg i en form tillsammans med den oskalade vitlöksklyftan och täck med folie.","Baka 35–40 minuter tills bitarna är helt mjuka. Ta av folien de sista 10 minuterna så ytan får lite färg och fukten går ur — det är det som ger en fastare och sötare kräm än kokning.","Mixa varm palsternacka med den urkramade vitlöken och smöret. Tillsätt grädden lite i taget, bara så mycket att mixern får fäste — massan ska vara tjock och tung, inte hällbar.","Passera genom finmaskig sil om du vill ha den helt slät, palsternacka har trådiga fibrer i mitten.","Smaka av med salt och några droppar citronsaft. Låt kallna i kylen minst en timme — smöret stelnar och krämen blir fast nog att formas till en quenelle."]},{"name":"Basilikadressing","steps":["Mixa basilika, parmesan, olivolja, citronsaft, honung och vitlök till en slät, ganska lös pesto — den ska gå att ringla i en tunn stråle.","Salta försiktigt, parmesanen saltar en del. Späd med kallt vatten om den är för tjock."]},{"name":"Sallad och montering","steps":["Skär morötterna i julienne, ca 2 × 2 mm. Skala gulbetan och skiva den rå på mandolin till 1–2 mm, dela skivorna på hälften till halvmånar. Vänd halvmånarna i lite citronsaft och en nypa salt och låt stå 10 minuter.","Kärna ur äpplet och skiva i 8 mm tjocka skivor. Vänd i citronsaft så de inte mörknar.","Riv eller skär salladen i grova bitar och lägg som ett tunt lager på fyra tallrikar, mest för volym och krisp.","Lägg det ljumma riset över salladen. Forma en fast quenelle av palsternackskrämen med två skedar och placera i mitten.","Fördela portabelloskivorna, moroten, gulbetan och äppelskivorna runt krämen. Strö över linsgroddar och mandlar — låt ungefär hälften av mandlarna vara hela och dela resten på längden.","Ringla över dressingen generöst och avsluta med flingsalt och svartpeppar."]}],"notes":[]},{"id":"3cfe56f597228086897cce4332ac4694","notion":"https://app.notion.com/p/3cfe56f597228086897cce4332ac4694","title":"Musselrisotto","intro":"Krämig risotto kokad på spadet från ångkokta blåmusslor med vitt vin.","plan":"","groups":[{"name":null,"items":[["1 kg","blåmusslor"],["3 dl","risottoris, arborio"],["2","schalottenlökar"],["3","vitlöksklyftor"],["2 dl","torrt vitt vin"],["8 dl","varm fisk- eller grönsaksbuljong"],["2 msk","olivolja"],["25 g","smör"],["50 g","riven parmesan"],["1","kruka persilja"],["","Salt och svartpeppar"]]}],"method":[{"name":null,"steps":["Rensa och tvätta musslorna. Kasta trasiga musslor och sådana som inte stänger sig när du knackar på dem.","Fräs hälften av löken och vitlöken i lite olja i en stor kastrull. Lägg i musslorna, häll på vinet och lägg på locket. Koka på hög värme i 3–4 minuter tills alla musslor öppnat sig.","Lyft upp musslorna och sila spadet. Blanda spadet med den varma buljongen. Plocka ur de flesta musslorna ur skalen, spara några med skal till dekoration.","Fräs resten av löken och vitlöken i olivolja i en separat kastrull tills de mjuknat. Tillsätt riset och fräs med någon minut tills det blir glansigt.","Späd med det varma mussel- och buljongspadet lite i taget under omrörning. Låt vätskan koka in innan du fyller på mer. Fortsätt cirka 18–22 minuter tills riset är krämigt men har tuggmotstånd.","Rör ner smör och parmesan. Vänd försiktigt ner musslorna så de blir varma. Smaka av med salt och peppar.","Toppa med hackad persilja och extra parmesan."]}],"notes":[]},{"id":"3d8e56f5972280f38057c7af5321ccc5","notion":"https://app.notion.com/p/3d8e56f5972280f38057c7af5321ccc5","title":"Lax med potatisklyftor och broccoli","intro":"Enkel vardagsmiddag med goda basråvaror med en yoghurtsås till.","plan":"1-2h utan förberedelser. Kan göras på 1h om man förenklar laxens tillagning eller gör något annat istället.","groups":[{"name":"Mains","items":[["Ca 1kg","lax"],["","Potatis ca 1kg"],["","Rotfrukter eventuellt (lagom, ca 0,5kg och minska potatis motsvarande ungefär)."],["2-3","broccolihuvuden"]]},{"name":"Yoghurtsås","items":[["","Turkisk yoghurt ca 3dl"],["1st","fetaost"],["","Salt + honung + svartpeppar"],["","Olivolja (eller annan)"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 225C.","(Skala) och dela potatis och rotfrukter i klyftor och passande skivor. Olivolja och salt på och blanda, därefter in i ugnen (helst var sin plåt för potatis/rotfrukter för o ta ut olika tider). Ca 30 min (känn efter).","Dela och skär upp broccolin i lagom storlek. Finhacka vitlök och blanda allt med olja och salt (inte för mycket salt).","Ändra ugnen till varmluft och kör in ca 15 min (känn efter).","Blanda nu ihop ingredienserna till yoghurtsåsen och ställ in i kylen.","Tillaga laxen gärna enligt:"]}],"notes":[]},{"id":"336e56f597228018af9be0ca56fd0b3c","notion":"https://app.notion.com/p/336e56f597228018af9be0ca56fd0b3c","title":"Ärtsoppa","intro":"Snabb ärtsoppa på frysta gröna ärtor med curry och ingefära. Från mamma.","plan":"","groups":[{"name":null,"items":[["1","gul lök, hackad"],["2","vitlöksklyftor, hackade"],["1–2 tsk","gul curry"],["1 msk","riven färsk ingefära"],["1","påse frysta gröna ärtor (ca 500 g)"],["Ca 7 dl","vatten"],["1","tärning kycklingbuljong"],["","Smör eller olja till stekning"]]}],"method":[{"name":null,"steps":["Stek löken mjuk i smör eller olja i en kastrull.","Tillsätt vitlöken och stek en kort stund. Rör ner curryn och låt fräsa någon halvminut utan att den bränns.","Tillsätt ingefäran och ärtorna. Häll på vatten så det ungefär täcker och smula i buljongtärningen.","Koka upp och låt koka några minuter tills ärtorna är mjuka.","Mixa slätt med stavmixer och servera.","Servera med en skiva surdegsbröd eller knäckebröd."]}],"notes":[]},{"id":"3eae56f59722800f8ccccf71c81a7ec0","notion":"https://app.notion.com/p/3eae56f59722800f8ccccf71c81a7ec0","title":"Gryta med vita bönor och kyckling","intro":"Snabb kycklinggryta med vita bönor och en blank sås av buljong, parmesan och smör – klar på 30 minuter, 4 portioner. Från ”Vardag”. Servera med potatismos, se sida till sist.","plan":"","groups":[{"name":null,"items":[["600 g","kycklinglårfilé"],["1","bananschalottenlök"],["2","vitlöksklyftor"],["2","kvistar rosmarin"],["1 dl","olivolja"],["400 g","färdigkokta vita bönor"],["2 dl","vitt vin"],["ca 8 dl","kycklingbuljong"],["","Majsstärkelse"],["100 g","parmesanost"],["75 g","smör"],["","Salt"]]}],"method":[{"name":null,"steps":["Börja med potatismoset.","Skär kycklingen i bitar. Finhacka lök, vitlök och rosmarin.","Fräs lök, vitlök och rosmarin i olivoljan på låg värme tills löken mjuknat.","Tillsätt kyckling och bönor och fräs försiktigt i ca 5 minuter.","Häll i vinet och låt det koka in nästan helt.","Tillsätt buljongen och låt sjuda ca 15 minuter, tills kycklingen är genomkokt och mör.","Red av med lite majsstärkelse till önskad konsistens.","Finriv parmesanen. Vispa ner smöret och rör sedan ner parmesanen. Smaka av med salt.","Servera med potatismos:"]}],"notes":[]},{"id":"3f7e56f597228194ad77fd3858ff7176","notion":"https://app.notion.com/p/3f7e56f597228194ad77fd3858ff7176","title":"CHECK Köttgryta med lök, koriander och fänkål","intro":"Mustig högrevsgryta med rostade koriander- och fänkålsfrön, tomatpuré och rödvin. 4 portioner.","plan":"20 min (skära och bryna köttet) + 15 min (fräsa lök och kryddor, koka in vinet) + 2 h (sjuda) + 5 min (reda av och smaka av)\nTotal: ca 2 h 40 min","groups":[{"name":null,"items":[["800 g","högrev"],["3","gula lökar"],["3","vitlöksklyftor"],["","Olja till stekning"],["2 msk","korianderfrön"],["2 msk","fänkålsfrön"],["1 ½ tsk","hel svartpeppar"],["4 msk","tomatpuré"],["2 dl","rött vin"],["","Vatten"],["","Eventuellt majsstärkelse"],["","Salt"]]}],"method":[{"name":null,"steps":["Skär högreven i mindre bitar och bryn köttet i omgångar i en stekpanna, cirka 20 minuter.","Grovhacka lök och vitlök och fräs dem i olja i en gryta, cirka 5 minuter.","Stöt korianderfrön, fänkålsfrön och svartpeppar. Tillsätt kryddorna och tomatpurén i grytan och fräs 1–2 minuter.","Lägg i köttet, tillsätt vinet och låt koka in, cirka 5 minuter.","Fyll på med vatten så att det täcker och sjud i cirka 2 timmar, tills köttet är mört.","Red eventuellt av med lite majsstärkelse och smaka av med salt, cirka 5 minuter."]}],"notes":[]},{"id":"3f7e56f5972281c4967ff6d50304c339","notion":"https://app.notion.com/p/3f7e56f5972281c4967ff6d50304c339","title":"CHECK Rostade kycklinglår med krämig majs och jalapeño","intro":"Ugnsrostade kycklinglår med krispigt skinn, serverade med stekt majs i en krämig sås med jalapeño och parmesan. 4 portioner.","plan":"15 min (sätta på ugnen och förbereda kycklingen) + 25 min (kycklingen i ugnen, majsen lagas under tiden)\nTotal: ca 40 min","groups":[{"name":"Kyckling","items":[["600 g","kycklinglårfilé eller kycklinglår med ben"],["","Olja"],["","Salt"],["","Svartpeppar"]]},{"name":"Krämig majs","items":[["400 g","majs på burk"],["3 msk","neutral olja"],["50 g","smör"],["½","jalapeño"],["2 dl","grädde"],["1 dl","färskost"],["50 g","parmesanost"],["","Salt"]]}],"method":[{"name":"Kyckling","steps":["Sätt ugnen på 225 grader, cirka 15 minuter.","Lägg kycklingen i en ugnsform eller på en plåt, ringla över olja och krydda med salt och peppar.","Tillaga i ugnen i cirka 20–25 minuter tills kycklingen är genomstekt och har fått ordentlig färg och krispigt skinn."]},{"name":"Krämig majs","steps":["Låt majsen rinna av ordentligt medan kycklingen är i ugnen. Hetta upp olja och smör i en stekpanna tills smöret börjar brynas lätt, cirka 2 minuter.","Stek majsen på medelvärme tills den får gyllenbrun färg, vätskan har stekts bort och den nästan börjar poppa i pannan, cirka 10 minuter.","Skiva jalapeñon fint och stek med i cirka 2 minuter.","Tillsätt grädde och färskost och låt sjuda ihop till en krämig stuvning, cirka 5 minuter.","Finriv parmesan och rör ner. Smaka av med salt.","Servera majsen med kycklingen och skeda över lite av stekskyn från kycklingen."]}],"notes":[]},{"id":"3b0e56f5972280afae2be67784a809dd","notion":"https://app.notion.com/p/3b0e56f5972280afae2be67784a809dd","title":"Fläskkarré low n slow i ugn","intro":"","plan":"","groups":[],"method":[],"notes":[{"heading":null,"lines":["Snake i ladan på cirka 1kg karré, siktade på 110C i grilltemp och tog kött på 82C innertemp. Kött från Ica. Saltade 3h innan. Blev 8/10 gott! Lite torrt, men mestadels jättegott.","Hemma 2:a augusti. Ugnen på 120C. Tog kött på 85C innertemp. Kött från Ica. Cirka 1kg. Saltade 2h innan. Körde grill på max sista 10 min med två bbq penslingar var femte min. Vilade 30 min. Blev gott, men rätt torrt i de gråare köttpartierna. 6/10.","Hemma 10:e augusti. Ugnen på 80C. Tog kött på 71C innertemp. Kött från lammet och bonden (fint stycke!). Cirka 1kg. Saltade 48h innan med 1,5% salt. Körde grill på max sista 10 min med en generös bbq pensling. Vilade 2h. Blev gott och saftigt, men lite tuggigt, vissa partier som fett och bindväv.","Osäker på vad jag vill testa nästa gång (vad som blir godast), men kanske testa att ta köttet på 76C innertemp? För att få lite mörare helhet än 71C men lite saftigare kött än 85C. Men mer kunskap krävs nog för att förstå processen och kalibrera mina förväntningar."]}]},{"id":"2a0e56f597228043a17aed519a702ca8","notion":"https://app.notion.com/p/2a0e56f597228043a17aed519a702ca8","title":"Hel kyckling Sous Vide","intro":"Hel kyckling som blir saftig och mör. Kan varieras med olika smaksättningar. Detta blev jättebra lördag 12:e september 2026.","plan":"","groups":[{"name":null,"items":[["1","hel kyckling (ca 1kg)"],["15g","salt"],["","Olivolja eller smör"],["","Timjan eller andra smaker"]]}],"method":[{"name":"Dag 1","steps":["Blanda salt och timjan och gnid in över hela ytan, även under bröstskinnet och i håligheten. (Kan binda benen för att hålla ihop hela)","Vakuumpacka och lägg i kylen minst 8h (över natten)."]},{"name":"Dag 2","steps":["Förbered vattenbad och ställ sous vide-cirkulatorn på 65 °C.","Sänk ned påsen helt under ytan och kör 5 timmar.","Ta upp kycklingen, spara skyn, häll ut vätskan ur håligheten och torka hela ytan noga.","Sätt ugnen på grill, 275 °C, med gallret högt upp.","Pensla kycklingen med olja och grilla högt upp 8–12 minuter tills skinnet är gyllene och krispigt. Håll uppsikt.","Låt vila 10 minuter. Stycka därefter till servering.","Koka under tiden ihop skyn till en sås om du vill."]}],"notes":[]},{"id":"2d8e56f5972280cf95add867144309e0","notion":"https://app.notion.com/p/2d8e56f5972280cf95add867144309e0","title":"Kycklinglår i TK","intro":"Kycklinglår i tryckkokare med gul lök och buljong. Buljongen sparas och skummas till nästa dag.","plan":"10 min (salta, hacka lök och bryna kycklingen) + 5 min (fräsa lök och tillsätta buljong) + 15 min (högt tryck) + 10 min (trycket byggs upp och släpps) Total: ca 40 min","groups":[{"name":null,"items":[["1kg","kycklinglår"],["3st","gula lökar"],["3","klyftor vitlök"],["1","tärning köttbuljong + 0.5L kokande vatten."]]}],"method":[{"name":null,"steps":["Salta kycklingen.","Hacka löken.","Torka och bryn kycklingen.","Förbered buljongen.","Ta ur kycklingen och fräs gullöken, allt i TK.","Häll i buljongen och blanda. Lägg i kycklingen.","Sätt tryckkokaren på 15 min, high.","Därefter släpp tryck och servera kycklingen. Klart, men:","Ta ifrån buljongen och kyl ner till nästa dag. Skimma mycket av fettet och använd i annat sammanhang. (Lite osäker på vad just nu)."]}],"notes":[]},{"id":"303e56f5972280a9a9d6cb724f2341b2","notion":"https://app.notion.com/p/303e56f5972280a9a9d6cb724f2341b2","title":"Slow Roasted Salmon (Samin)","intro":"Hel laxsida som bakas långsamt på 110 °C med bara olivolja och salt, saftig och jämnt tillagad.","plan":"5 min (förbereda laxen) + ca 40 min (i ugnen, kolla innertemp från 20 min) + 5 min (vila) Total: ca 50 min","groups":[{"name":null,"items":[["","Laxsida"],["","Salt"],["","Olivolja"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 110 C.","Förbered laxen. Lägg laxen på en plåt, gärna aluminiumplåten. Ringla olivolja och salt över hela.","In i ugnen i cirka 40 min, börja med 20 min och kolla därefter i 10 eller 5 min intervaller beroende på temp.","Kolla av innertemp och sikta på"]}],"notes":[{"heading":"Innertemperaturer","lines":["Medium-rare (48-52°C): Laxen har en tydligt mörkare och råare kärna.","Klassisk/Medel (52-56°C): Laxen är genomvarm, saftig och delar sig lätt i skivor.","Välstekt (60°C): Laxen är helt fast och torr, men kan föredras av vissa."]},{"heading":"Tips","lines":["Låt vila: Temperaturen stiger ofta 1-2 grader efter att den tagits ur ugnen."]}]},{"id":"3bfe56f597228052bfcdea25fcf93b8c","notion":"https://app.notion.com/p/3bfe56f597228052bfcdea25fcf93b8c","title":"Bräserad vildsvinskulting","intro":"Halv vildsvinskulting som går hela dagen i ugnen på låg temperatur. Första gången med Jonathan och Lovisa, med kött från Jonathan.","plan":"","groups":[{"name":null,"items":[["1","halv vildsvinskulting, ca 4 kg"],["50 g","salt"]]},{"name":"Vätskor","items":[["3 dl","kombucha/vatten och med lite vinäger"],["2 dl","kycklingbuljong"],["1 dl","torrt vitt vin"],["2","gula lökar, i klyftor"],["4","vitlöksklyftor, hela"],["2","lagerblad"],["2","morötter, i grova bitar"],["2 tsk","svartpeppar, grovkrossad"],["1 msk","tomatpuré"]]},{"name":"Ytterligare marinad/smaksättnig (inte testat)","items":[["6","vitlöksklyftor, krossade"],["1","knippe timjan"],["1 msk","fänkålsfrö"],["1 msk","dijonsenap"],["1 msk","smör"]]}],"method":[{"name":null,"steps":["Gnid in kultingen med salt. (Krossad vitlök, timjan, fänkålsfrö och svartpeppar).","Lägg oinpackad i kylen över natten.","Sätt ugnen på 95 °C. Lägg kultingen i en djup långpanna.","Lägg i lök, morot, hela vitlöksklyftor, svartpeppar och lagerblad runt köttet. Rör ut tomatpurén i kombucha, buljong och vin och häll i, så att vätskan når halvvägs upp på låret.","Täck långpannan absolut tätt med dubbel folie (viktigt med dubbel folie), vikt ordentligt över kanterna. Otät folie torkar ut köttet.","Ställ in i ugnen och låt gå 9 timmar. Köttet är klart när det lossnar från benen.","Ta ut långpannan, lyft över köttet och låt vila inslaget i folie och handduk.","Sila skyn och skumma av fettet och koka ihop till hälften, smaka av med salt (och dijonsenap).","Plocka köttet i grova bitar, häll över skyn."]}],"notes":[]},{"id":"3bfe56f59722805b89b0db1229bbb3ad","notion":"https://app.notion.com/p/3bfe56f59722805b89b0db1229bbb3ad","title":"Bräserade vildsvinsrevben med BBQ-glaze","intro":"Vildsvinsrevben som går hela dagen på låg temperatur (tillsammans med kultingen), och glazeas på slutet. Gjorde första gången med Jonathan och Lovisa, kött från Jonathan.","plan":"","groups":[{"name":null,"items":[["1,3 kg","vildsvinsrevben i ett helt stycke"],["26g","salt"],["2 msk","socker"],["1 tsk","svartpeppar, grovkrossad"],["1 dl","vatten"],["1 msk","äppelcidervinäger"]]}],"method":[{"name":null,"steps":["Kvällen innan: låt hinnan på revbenens undersida sitta kvar — den håller ihop stycket under den långa tillagningen. Gnid in revbenen med salt, socker, peppar och lägg i kylen över natten.","Sätt ugnen på 95 °C. Lägg revbenen i en form/stekpanna som är precis så stor att de får plats, med köttsidan uppåt. Häll i vatten och 1 msk äppelcidervinäger.","Alt. 1: Sätt lock på stekpannan Alt. 2: Täck formen med folie och nyp fast den under kanten hela vägen runt, så att ingen ånga läcker ut.","Ställ in på nedre falsen i 9 timmar.","Ta fram BBQ-sås.","Ta av folien och häll av vätskan (spara den till skyn, den är koncentrerad och söt).","Höj ugnen till 220 °C.","Pensla revbenen med glazen och kör dem 10 minuter i mitten av ugnen. Pensla en gång till efter 5 minuter.","Låt vila 10 minuter och skär mellan benen."]}],"notes":[]},{"id":"283e56f5972280579a7ad600bc1b94ef","notion":"https://app.notion.com/p/283e56f5972280579a7ad600bc1b94ef","title":"Fransk Potatisgratäng","intro":"Klassisk svensk/fransk potatisgratäng.","plan":"15 min (skiva potatis, riva ost och blanda, medan ugnen blir varm) + 50–60 min (i ugnen) + 15 min (vila) Total: ca 1,5 h","groups":[{"name":null,"items":[["1kg","fast (höst- eller vinterpotatis)"],["3","vitlöksklyftor finhackade"],["3dl","riven ost (välj utifrån smak, grevé)"],["2tsk","salt"],["1/2 tsk","svartpeppar"],["2dl","mjölk"],["1,5dl","vispgrädde"],["","Smör eller olja till formen."]]}],"method":[{"name":null,"steps":["Sätt ugnen på 200 C vanlig.","Skiva potatisen på tunnaste i matberedaren (ca 2mm)","Riv osten på matberedarens grova.","Smörj ugnsform med smör/olja.","Blanda följande i bunke:\n- All potatis\n- Vitlöken\n- Saltet\n- Pepparn\n- Mjölken\n- Vispgrädden\n- Hälften av osten","Häll ut i formen och på med resten av osten. (Eller vänta med osten till det är 20 min kvar).","50-60 min i ugn, pröva med sticka för att känna av.","Låt gratängen vila cirka 15 minuter innan servering."]}],"notes":[]},{"id":"2bbe56f59722805d91c9e7fe5c0f82ae","notion":"https://app.notion.com/p/2bbe56f59722805d91c9e7fe5c0f82ae","title":"Potatismos","intro":"Klassiskt potatismos.","plan":"","groups":[{"name":null,"items":[["1kg","potatis fast"],["1dl","vispgrädde"],["1-2 dl","mjölk eller mer"],["50g","smör"],["1tsk","salt"],["1krm","socker"]]}],"method":[{"name":null,"steps":["Skala och skär potatisen i jämnstora bitar, lägg i kallt vatten medans du arbetar med resterande.","Koka i saltat vatten tills mjuka, cirka 15-20 om de är små, 30-40 om de är stora bitar.","Häll av vattnet och ånga av potatisen.","Värm under tiden mjölken och smöret.","Passera potatisen på grövsta.","Blanda med mjölken och smöret.","Smaka av med salt (peppar och socker).","Servera."]}],"notes":[{"heading":"V1:","lines":["1kg potatis (50/50 fast/mjölig) (sist hade jag bara farmor och farfars som väl är mjöliga)","2,5dl mjölk","50g smör","1tsk salt","1krm socker"]}]},{"id":"3b8e56f59722800ebf95f80e8b254ea5","notion":"https://app.notion.com/p/3b8e56f59722800ebf95f80e8b254ea5","title":"Gurksallad Krispig","intro":"Frisk sallad med krispig gurka, rödlök, fetaost och mycket dill.","plan":"15 min (skära, hacka och blanda) Total: ca 15 min","groups":[{"name":null,"items":[["2","gurkor (Tildas krispiga)"],["1","rödlök"],["1 paket","fetaost"],["1","knippe dill"],["","Olivolja, salt, peppar, vitvinsvinäger"]]}],"method":[{"name":null,"steps":["Skala gurkorna och hacka de i 1cm tjocka skivor och dela varje skiva i fyra.","Dela rödlöken i två halvor och hacka i tunna skivor.","Ta en stor skål och smula fetaosten över gurkan och rödlöken.","Finhacka dillen så fint du kan utan upprepning.","Ringla olivolja, lite vitvinsvinäger och peppar över. Salta precis innan servering."]}],"notes":[]},{"id":"3d1e56f597228073897ff20468e68e11","notion":"https://app.notion.com/p/3d1e56f597228073897ff20468e68e11","title":"Västerbottenpaj","intro":"Klassisk paj med Västerbottensost — 8 portioner, från ICA.","plan":"","groups":[{"name":"Pajdeg","items":[["2 dl","vetemjöl"],["1 dl","fullkornsmjöl"],["125 g","smör"],["1","ägg"],["1tsk","kumminfrön"]]},{"name":"Fyllning","items":[["4","ägg"],["2 1/2 dl","vispgrädde (40 %)"],["1 dl","mjölk"],["300 g","Västerbottensost"],["2 krm","salt"],["1 krm","svartpeppar"]]},{"name":"Garnering","items":[["","Gräddfil"],["","Löjrom eller stenbitsrom"],["","Hackad gräslök"]]}],"method":[{"name":null,"steps":["Blanda vetemjöl, fullkornsmjöl, kumminfrön och smör. Tillsätt ägget och blanda snabbt ihop till en deg.","Smörj pajformen med smör.","Tryck ut degen i pajformen, ca 25 cm i diameter. Låt vila i kylen 30 minuter.","Sätt ugnen på 200°C, över- och undervärme.","Nagga botten med en gaffel och förgrädda skalet mitt i ugnen 10–15 minuter.","Sänk ugnen till 175°C.","Vispa ihop ägg, grädde och mjölk.","Riv osten och blanda ner den i äggblandningen tillsammans med salt och svartpeppar.","Häll fyllningen i pajskalet och grädda mitt i ugnen ca 50 minuter, tills fyllningen stannat och pajen fått fin färg.","Garnera med gräddfil, rom och hackad gräslök."]}],"notes":[]},{"id":"3dae56f5972280a0abbbdfb03c28a4a9","notion":"https://app.notion.com/p/3dae56f5972280a0abbbdfb03c28a4a9","title":"Rostade Tomathalvor","intro":"Rostade halvor, söta och lite syrliga beroende på sort. Bränn av högst upp till sist.","plan":"5 min (prepp) + 30–50 min (i ugn) Total: ca 40–60 min","groups":[{"name":null,"items":[["","Tomater till att täcka en plåt luftigt"],["","Olivolja"],["","Salt"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 200C.","Dela tomaterna i halvor.","Blanda med olivolja och salt i en bunke.","Fördela luftigt på en plåt. Ställ in i mitten av ugnen.","Grilla till sist av för att få färg, högst upp i ugnen med grill på max.","Låt svalna något till servering."]}],"notes":[]},{"id":"3dae56f597228003b7c4f88b576d565c","notion":"https://app.notion.com/p/3dae56f597228003b7c4f88b576d565c","title":"Stuvad vitkål","intro":"Stuvad vitkål, med mjölk (kan göras med mer grädde eller bara grädde men behövs verkligen inte).","plan":"Total: ca 30 min","groups":[{"name":null,"items":[["800g","vitkål"],["4msk","smör"],["6msk","vetemjöl"],["1L","mjölk"],["1tsk","salt"],["3krm","vitpeppar"]]}],"method":[{"name":null,"steps":["Ansa vitkålen (ta bort de yttersta skadade eller solkiga bladen, dela huvudet på mitten och skär bort den hårda rotstocken).","Skär den i cirka 2 cm stora bitar.","Smält matfettet i en gryta, lägg i kålen och rör om väl så att all kål blir glansig.","Strö över mjölet och rör om. Späd med mjölken och låt allt koka upp under omrörning (bränner lätt i pannan).","Krydda med salt och nymald vitpeppar.","Låt kålen koka på svag värme under lock tills den är mjuk, ca 15 min. Späd sommarkål behöver bara ca 5 min.","Servera."]}],"notes":[]},{"id":"2dbe56f5972280f09abbc0cc77ee98ea","notion":"https://app.notion.com/p/2dbe56f5972280f09abbc0cc77ee98ea","title":"Dijondressing","intro":"Enkel dressing på dijonsenap, olivolja, äppelcidervinäger och honung.","plan":"5 min (blanda och smaka av) Total: ca 5 min","groups":[{"name":null,"items":[["2 msk","Dijonsenap (strykta, eller mindre, ej mer, men smaka av såklart)."],["1 dl","olivolja"],["2,5 msk","äppelcidervinäger"],["2 krm","salt"],["1 tsk","honung"]]}],"method":[{"name":null,"steps":["Blanda allt i en bägare och mixa med stavmixer (eller bara blanda).","Smaka av med salt, honung, äppelcidervinäger."]}],"notes":[]},{"id":"2dee56f597228047860feff9280e8a2c","notion":"https://app.notion.com/p/2dee56f597228047860feff9280e8a2c","title":"Inläggning: 1-2-3-lag","intro":"Grundlag för snabbinläggning: 1 del ättiksprit, 2 delar socker, 3 delar vatten.","plan":"10 min (förbereda grönsakerna) + 5 min (koka lagen) + 15 min (svalna) + 1 h (i kylen) Total: ca 1,5 h","groups":[{"name":null,"items":[["1dl","ättikssprit 12%"],["2dl","strösocker"],["3dl","vatten"]]}],"method":[{"name":null,"steps":["Förbered det som ska läggas in, tunna skivor eller så.","Koka upp vatten, socker och ättikssprit i en kastrull. Rör runt tills sockret har löst sig.","Låt lagen svalna något och häll därefter över det som ska läggas in.","Låt kallna och ställ därefter i kyl minst en timme innan servering. (Men går ju att äta innan)."]}],"notes":[{"heading":null,"lines":["Picklad rödlök håller minst en vecka, upp till en månad."]}]},{"id":"3bae56f5972280f799d9deab469ba282","notion":"https://app.notion.com/p/3bae56f5972280f799d9deab469ba282","title":"Dry Brine principles","intro":"Principer för torrsaltning av kött och fågel: saltmängd, tider och tillägg.","plan":"45 min–4 h (små kycklingbitar) / 12–24 h (karré, hel kyckling) / 24–72 h (stora detaljer) Total: 45 min–72 h beroende på storlek","groups":[],"method":[],"notes":[{"heading":"Generellt","lines":["0,75–1,5 % salt räknat på köttets vikt. Alltså 7,5–15 g salt per kg kött. Beroende på storleken på bitarna/proteinet. Ju större, ju högre procent.","Salta hela ytan jämnt och lägg köttet oövertäckt på galler i kyl. Ingen vätska tillsätts — saltet drar ut fukt, löser sig i den och sugs sedan tillbaka in.","Tiden anpassas efter storlek på protein.","  Små bitar kyckling: 1–4h (minst 45 min).","  Fläskkarré, hel kyckling: 12–24h.","  Stora detaljer, flera kg: 24–72h.","Svårare att översalta än våtlake — du styr total saltmängd på vikten, så längre tid = torrare, bättre uppdragen yta snarare än saltare kött.","Ska inte sköljas. Poängen är den torra, uppdragna ytan som ger bättre bryning och krispigt skinn.","Klappa ev. bort synligt kvarvarande salt/fukt innan tillagning, men behåll ytan torr."]},{"heading":"Tillägg","lines":["Socker (hälften av saltmängden) för bryning och färg.","Torra aromater: mald peppar, vitlökspulver, torkad timjan, etc. Färska/våta aromater fungerar sämre då de motverkar upptorkningen.","Bakpulver (en nypa, ca 0,25 %) på skinn/yta ger extra krispighet — bra på fågel."]}]},{"id":"3bae56f59722802ebf8bd09a984605a7","notion":"https://app.notion.com/p/3bae56f59722802ebf8bd09a984605a7","title":"Wet Brine principles","intro":"Principer för saltlake till kött och fågel: styrka, tider och tillägg.","plan":"30 min–24 h (i lake beroende på storlek) + 1–12 h (torka upp ytan i kylen, valfritt) Total: 30 min–36 h beroende på storlek","groups":[],"method":[],"notes":[{"heading":"Generellt","lines":["5-8% salt per liter vatten. Alltså 50–80 g salt per liter vatten.","Tiden anpassas efter storlek på protein.","  Små bitar kyckling: 30 min – 2h.","  Fläskkarré, hel kyckling: 4-12h.","  Stora detaljer, flera kg: 12-24h.","För länge i för starkt ger översalt smak och gummitextur, skinkigt.","Kan sköljas för att undvika för salt yta.","Kan ställas tillbaka i kylskåp på galler, för att torka upp ytan, 1-12h."]},{"heading":"Tillägg","lines":["Socker (hälften av saltmängden).","Aromater: lagerblad, peppar, vitlök, etc."]}]},{"id":"31be56f5972280238a08f467e0fa4128","notion":"https://app.notion.com/p/31be56f5972280238a08f467e0fa4128","title":"Baljväxter / Bönor","intro":"Grunder för att blötlägga och koka torra baljväxter så att de blir lättsmälta.","plan":"18–24 h (blötlägga i kylen) + ? (koka, beror på sort) Total: ?","groups":[],"method":[{"name":"Förberedelser","steps":["Blötlägg helst i 18-24h i kylskåp.","Byt gärna vattnet en gång.","Skölj i 20-30 sek innan du kokar.","Koka i nytt vatten.","Använd lite mindre ett tag för att vänja sig."]}],"notes":[]},{"id":"261e56f5972280a8b518c4037e446221","notion":"https://app.notion.com/p/261e56f5972280a8b518c4037e446221","title":"Chia Bircher Bowl","intro":"Från Whole Food Cooking Every Day. Vitamixa första delen på max och häll sedan i resten och blanda på lägsta, bara för att få det blandat. Blanda ett par gånger under cirka 30 min och därefter kyl över natten. Kan stå i kyl i upp till fyra dygn.","plan":"5 min (mixa och blanda) + 30 min (rör om några gånger) + över natten (i kylen) Total: ca 35 min + över natten","groups":[{"name":"Mixa hårt","items":[["70g","mandlar"],["1-2","dadlar (beroende på storlek)"],["660g","vatten"],["2tsk","kanel"],["2","nypor salt"]]},{"name":"Blanda sedan","items":[["50g","havregryn"],["40g","chiafrön"],["40g","linfrön (hampafrön)"]]}],"method":[],"notes":[]},{"id":"3a9e56f5972280fab55edbc215cf7e4a","notion":"https://app.notion.com/p/3a9e56f5972280fab55edbc215cf7e4a","title":"Fattiga riddare","intro":"Klassiska franska riddare på toastbröd doppat i äggsmet, stekt gyllenbrunt och toppat med kanelsocker. Kan serveras med vispgrädde och hallon.","plan":"5 min (vispa smet och grädde) + 10 min (doppa och steka skivorna) Total: ca 15 min","groups":[{"name":null,"items":[["1","ägg"],["1 dl","mjölk"],["1 msk","vetemjöl"],["0,5 krm","salt"],["3 skivor","bröd (toastbröd)"],["1 msk","smör"],["1 tsk","kanel"],["3 msk","strösocker"],["0,5 dl","vispgrädde"],["100 g","färska eller tinade svenska hallon"]]}],"method":[{"name":null,"steps":["Vispa ihop ägg, mjölk, mjöl och salt i en bunke. Tryck ner första brödskivan medan pannan värms upp. Lägg därefter i nästa skiva när första steks i smör, cirka 1 minut på varje sida.","Blanda kanel och socker och strö det över de nystekta riddarna.","Vispa grädden och servera till riddarna tillsammans med hallon."]}],"notes":[]},{"id":"3fce56f597228135bed1e86a15dc8ca0","notion":"https://app.notion.com/p/3fce56f597228135bed1e86a15dc8ca0","title":"Snabb aioli","intro":"Snabb aioli med stavmixer, från ICA. Ger ca 2,5 dl.","plan":"30 min (rumstempera ägg m.m.) + 5 min (riva och mixa) Total: ca 35 min","groups":[{"name":null,"items":[["3 g","vitlök (1 liten kläfta)"],["5 g","dijonsenap (1 tsk)"],["5 g","vitvinsvinäger (1 tsk)"],["1 g","salt (1 krm)"],["50 g","ägg (1 st)"],["185 g","rapsolja (2 dl)"],["","Svartpeppar"]]}],"method":[{"name":null,"steps":["Se till att alla ingredienser håller samma temperatur, ta fram ägg och vinäger ur kylen i god tid, cirka 30 minuter.","Skala och riv vitlöken fint.","Häll oljan i en hög och smal bunke (max ca 8 cm i diameter) och lägg i vitlök, senap, vinäger, salt och ägg.","Sätt mixerstaven i botten av bunken, starta den och lyft den sakta upp mot ytan, cirka 1 minut.","Smaka av med svartpeppar och eventuellt mer salt och vinäger."]}],"notes":[]},{"id":"251e56f5972280d7b5d9dec0ea377d87","notion":"https://app.notion.com/p/251e56f5972280d7b5d9dec0ea377d87","title":"Stir Fry","intro":"Stir-Fry med en bas av tofu eller kyckling grönsaker och sås. Middag, kan vara lunch eller matlådor.","plan":"","groups":[{"name":null,"items":[["","Tofu 400g / Kyckling 400g"]]},{"name":"Veggies","items":[["","Broccoli 1st"],["","Zucchini 1st"],["","Purjolök 1/3 - 1/2"],["","Salladslök 2st"]]},{"name":"Sås","items":[["","Gochujang 4msk"],["","Socker 4msk"],["","Soja 4msk (kinesisk ljus)"],["","(Justera efter smak)"]]},{"name":null,"items":[["","Jasminris 2 riskoppar (rk)"]]}],"method":[{"name":null,"steps":["Sätt igång riskokaren med 2 rk ris och 2,4 rk vatten, ett par nypor salt.","Stek tofu i bitar i nonstick-panna, ganska länge.","Stek grönsaker i lagom mängd/omgång hackade i bra bite-size bitar.","Fräs purjolök och vita delen av salladslöken.","Värm upp såsen och blanda i grönsaker och tofu.","Ringla gröna delen av skivade salladslöken."]}],"notes":[{"heading":"Alternativ","lines":["Stek kyckling istället för tofu.","Byt ut zucchini mot Pak Choi.","Byt sås."]},{"heading":"Adderingar","lines":["Skivade sockerärtor (sugar-snaps), snabbstekta.","Enoki, stekta.","Färsk chili.","Vitlök till såsen (lite fräst).","Thaibasilika i slutet. Den som smakar lite lakrits, inte holy basil.","Ingefära, riven eller superfinhackad.","Edamame bönor.","Tunna skivor av fänkål?","Toppa med sesamfrön/jordnötter/cashew.","Kimchi."]}]},{"id":"301e56f59722800cb25fd00406817723","notion":"https://app.notion.com/p/301e56f59722800cb25fd00406817723","title":"Pho Ga Vietnamesisk kycklingpho","intro":"Klassisk vietnamesisk pho med kycklingbuljong och kryddor. Recept av Nagi Maehashi / RecipeTin Eats.","plan":"","groups":[{"name":null,"items":[["1 msk","neutral olja"],["2","lökar, halverade (skal på är ok)"],["5 cm","ingefära, skivad ca 7 mm tjock (oskalad)"],["2 liter","vatten"],["1,5 kg","kycklinglår med ben och skinn"],["5","stjärnanis"],["1","kanelstång"],["4","kryddnejlikor"],["2 tsk","fänkålsfrön"],["2 tsk","korianderfrön"],["8 tsk","fisksås"],["6 tsk","strösocker"],["¾ tsk","salt (grovt) eller ½ tsk bordsalt"],["360 g","torkade risnudlar, tunna och platta (eller 600 g färska)"],["2","salladslöksstjälkar, fint skivade"]]},{"name":"Tillbehör","items":[["3 dl","böngroddar"],["1","litet knippe vardera av thaibasilika, mynta och koriander"],["2","limefrukter, delade i klyftor"],["","Hoisinsås"],["","Sriracha"],["","Röd chili, fint skivad (valfritt)"]]}],"method":[{"name":null,"steps":["Hetta upp oljan i en stor gryta (minst 6 liter) på hög värme. Lägg löken och ingefäran med snittytan nedåt och låt stå orört i 2 minuter tills de svartnar. Vänd och låt stå ytterligare 2 minuter.","Tillsätt vatten och alla buljongsingredienser utom salt. Koka upp och sänk sedan värmen så att det puttrar mycket försiktigt med locket på glänt.","Låt puttra i 1,5 timme. Skumma av grumset som stiger upp till ytan ett par gånger under tillagningen.","Ta upp kycklingen. Sila buljongen i en ren gryta – du ska ha ca 1,5 liter. Har du mer, reducera. Har du mindre, fyll på med vatten.","Tillsätt salt och låt buljongen sjuda försiktigt. Den ska smaka lite väl salt – det späds ut av nudlarna.","Strimla kycklingköttet, kassera ben och skinn. Håll buljongen varm till servering.","Ställ fram tillbehören på bordet. Tillaga nudlarna enligt förpackningens anvisningar precis innan servering och låt dem rinna av väl.","Lägg nudlar i skålar, toppa med kyckling och häll över ca 3,75 dl buljong per portion. Strö över salladslök. Servera omedelbart med tillbehören vid sidan om."]}],"notes":[]},{"id":"387e56f5972280fb89a7defb3652cf21","notion":"https://app.notion.com/p/387e56f5972280fb89a7defb3652cf21","title":"Slow laxsida med soja, lime och ingefära","intro":"Långsamt ugnsbakad laxsida med soja-, lime- och ingefärsglaze, serverad som bowl med krispiga toppings och en enkel chilisås.","plan":"","groups":[{"name":"Lax","items":[["1","hel laxsida"],["3–4 msk","soja"],["1–2 msk","honung"],["1","lime, saft och rivet skal"],["1–2","vitlöksklyftor, finrivna"],["1","bit färsk ingefära, finriven"],["1–2 tsk","sesamolja"],["","Svartpeppar"],["","Chili efter smak"]]},{"name":"Mise en place till bowl","items":[["","Gurka i stavar eller halvmånar"],["","Morot i tunna stavar"],["","Rödkål eller spetskål, fint strimlad"],["","Salladslök, tunt på snedden"],["","Chili, tunt skivad"],["","Limeklyftor"],["","Persilja eller mynta"],["","Sesamfrön"],["","Picklad rödlök"],["","(Mango och avokado i tärningar)"]]},{"name":"Sås","items":[["2 dl","yoghurt, crème fraîche eller majonnäs"],["","Limejuice"],["","Lite soja"],["","Sriracha eller chili"],["","En nypa salt"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 100–120 °C. Lägg laxsidan på bakplåtspapper, skinnsidan nedåt om skinnet är kvar.","Blanda soja, honung, lime, vitlök, ingefära, sesamolja och peppar till en glaze. Pensla över laxen. Spara gärna lite glaze till servering, men bara om den inte varit i kontakt med rå fisk.","Baka långsamt i mitten av ugnen i cirka 35–55 minuter beroende på tjocklek och temperatur. Sikta på en innertemperatur runt 42–45 °C för väldigt saftig och mjuk lax, 46–50 °C för lite fastare men fortfarande saftig, eller 52 °C+ för mer genomlagad.","Ta ut laxen och låt vila några minuter. Skeda över extra glaze, limejuice och sesamfrön precis före servering.","Preppa all mise en place i små skålar medan laxen går i ugnen.","Rör ihop såsen.","Servera med ris eller nudlar, laxen i stora mjuka bitar och all mise en place runtom."]}],"notes":[]},{"id":"2e1e56f5972280e38133ce5e4914b774","notion":"https://app.notion.com/p/2e1e56f5972280e38133ce5e4914b774","title":"Glazed Thick Ribs TK","intro":"","plan":"","groups":[{"name":"Ribs i buljong","items":[["1kg","tjocka knäckta revben"],["2st","gula lökar"],["15","svartpepparkorn"],["3st","lagerblad"],["2st","köttbuljongtärningar"],["1L","vatten"],["2tsk","salt"]]},{"name":"Glaze","items":[["0,75dl","hoisinsås"],["0,75dl","oystersås"],["2msk","flytande honung"],["3","klyftor vitlök, skalade och rivna"],["1,5tsk","svart risvinäger"],["","Salt att smaka av med"]]}],"method":[{"name":"Koka Ribs","steps":["Skala och skär lökarna i klyftor.","Koka upp 1L vatten i TK-kastrullen och tillsätt buljongtärningarna, blanda så de löser sig.","Lägg i lökklyftorna, svartpepparkornen, lagerbladen och revbenen. (Första gången lade vi ner hela köttbiten i ett stycke, ej delad i mindre bitar).","Sätt igång TK på high i 50-60 min beroende på om du tar 10 min natural release.","Följ instruktioner under “Glaze” efter detta."]},{"name":"Glaze","steps":["Blanda ihop alla ingredienser till glazen.","När det börjar närma sig klart i TK, så sätt ugnen på 225 C.","Pensla sedan de kokta revbenen runtom hela med glaze, och lägg på en ugnssäker form. Men spara glaze till senare (och om det är för mycket).","Sätt in de i ugnen på 20 minuter, men vänd alla efter ca 10 min när de fått lite yta/färg och lägg glaze på igen.","Servera."]}],"notes":[]},{"id":"2e1e56f5972280ceab5cfb45fdcb85f7","notion":"https://app.notion.com/p/2e1e56f5972280ceab5cfb45fdcb85f7","title":"Umami Drumsticks TK","intro":"","plan":"","groups":[{"name":"Kyckling \u0026amp; aromatics","items":[["1kg","kycklingben (drumsticks)"],["1/4","purjolök eller 3 salladslökar"],["4","klyftor vitlök krossade/hackade"],["2cm","ingefära i skivor"]]},{"name":"Sojablandning","items":[["1dl","light soy sauce"],["0,5dl","dark soy sauce"],["0,5dl","Shaoxing wine"],["1msk","sesamolja"],["0,5dl","råsocker/brunt socker"],["1dl","vatten"],["2st","stjärnanis"],["3st","lagerblad"]]}],"method":[{"name":null,"steps":["Kycklingklubbor (frysta tinade eller färska) ska helst vara i rumstemperatur och torkas av.","Hetta upp en stor stekpanna tills riktigt varm.","Förbered och hacka under tiden purjolöken, ingefäran och vitlöken.","I med olja och bryn kycklingklubborna. (Stänkskydd kan vara bra).","Vänd klubborna när de brynts på ena sidan.","Blanda under tiden resterande ingredienser till koket.","När klubborna brynts på båda sidor kan de läggas i tryckkokarens kastrull och vänta på resterande ingredienser.","Fräs purjolöken, vitlöken och ingefäran i samma stekpanna som använts till klubborna.","När de mjuknat och fått lite färg, häll då i sojablandningen och få upp det i temp tills det sjuder, skrapa stekpannan, häll sedan i allt i tryckkokaren över klubborna.","Sätt tryckkokaren på high 5 min + 5 min natural release. (Du kan testa att köra 1 min high och 10 min natural release nästa gång och ta innertemp). (Eftersom 5+5 blev lite över men gott).","Servera kycklingklubborna direkt från tryckkokaren och använd buljongen som sås till ris."]}],"notes":[{"heading":null,"lines":["Första gången jag gjorde detta gjorde jag ett kokad broccoli med dressing."]}]},{"id":"2e1e56f597228056bd85ed563949841a","notion":"https://app.notion.com/p/2e1e56f597228056bd85ed563949841a","title":"Fresh Broccoli Coat","intro":"","plan":"","groups":[{"name":null,"items":[["1st","broccoli"],["1msk","vitvinsvinäger"],["1tsk","honung"],["1tsk","sesamolja"],["1tsk","gochugaru"],["","Nypa salt"]]}],"method":[{"name":null,"steps":["Dela upp broccolin i sina små buketter, och sedan i mindre buketter för att vara trevliga i en tugga.","Koka upp rikligt med vatten, salta halvvägs till pastavatten.","Koka broccolin i 1,5 min och skölj med kallt vatten direkt efter. Låt rinna av en stund för att torka upp.","Blanda övriga ingredienser i en skål, smaka av.","Tossa broccolin i dressingen. Servera."]}],"notes":[]},{"id":"3bfe56f597228063b9e6cee94ae6cecd","notion":"https://app.notion.com/p/3bfe56f597228063b9e6cee94ae6cecd","title":"Shrimp noodle sallad","intro":"","plan":"","groups":[{"name":null,"items":[["400g","Risnudlar M"],["400g","vannameiräkor"],["","Halvt huvud romansallad"],["","Vitlök"],["","Risvinäger/Lime/Vitvinsvinäger"]]}],"method":[],"notes":[]},{"id":"373e56f59722803db7b1f70ea13b000e","notion":"https://app.notion.com/p/373e56f59722803db7b1f70ea13b000e","title":"Dal palak","intro":"Indisk linsgryta med spenat och tempererade hela kryddor, från Bon Appétit (Epicurious).","plan":"","groups":[{"name":null,"items":[["200 g","röda linser (masoor dal)"],["¼ tsk","malen gurkmeja"],["1","lime, halverad"],["1 tsk","salt, delat, plus mer efter smak"],["30 g","ghee eller osaltat smör"],["½ tsk","svarta senapsfrön"],["½ tsk","hela spiskumminfrön"],["½ tsk","fänkålsfrön"],["1","liten torkad röd chili, bruten på mitten"],["1","liten gul lök, grovhackad"],["2","vitlöksklyftor, finhackade"],["1 tsk","finriven färsk ingefära"],["90 g","spenat, grovhackad"],["","Kokt ris, korianderblad och limeklyftor, till servering"]]}],"method":[{"name":"Steg 1","steps":["Skölj linserna i en finmaskig sil. Lägg dem i en medelstor kastrull och häll i 6 dl vatten. Koka upp på hög värme (håll koll, det kan lätt koka över).","Låt koka och skumma av ytan tills blandningen slutar skumma, ca 3 minuter.","Rör i gurkmejan, sänk till medel–låg värme, lägg på lock på glänt och låt sjuda tills linserna är mjuka, 25–30 minuter.","Ta från värmen, pressa i saften från en limehalva och rör i ca ½ tsk salt.","Börja koka ris."]},{"name":"Steg 2","steps":["Förvärm en stekpanna.","Hacka gullöken.","Riv ingefäran och finhacka vitlöken.","Lägg ihop kryddorna i en liten skål, och chilin separat.","Smält samtidigt gheet/smöret i en djup stekpanna på medelhög värme.","Tillsätt senaps-, spiskummin- och fänkålsfrön och fräs några sekunder tills senapsfröna börjar poppa och oljan kring fröna fräser.","Sänk till medelvärme, tillsätt chilin och rör runt.","Tillsätt löken och fräs under omrörning tills den är genomskinlig och mjuk, ca 5 minuter.","Tillsätt vitlök och ingefära och fräs tills det doftar, ca 30 sekunder."]},{"name":"Steg 3","steps":["Lägg i spenaten och ca ¼ tsk salt och fräs under omrörning tills spenaten faller ihop men fortfarande är klargrön, ca 1 minut.","Ta från värmen och pressa i saften från den andra limehalvan.","Rör ner spenatblandningen i linserna och smaka av med salt.","Fördela ris och dal i skålar, (toppa med koriander) och servera med limeklyftor."]}],"notes":[]},{"id":"373e56f5972280bdb2d5c931177781f8","notion":"https://app.notion.com/p/373e56f5972280bdb2d5c931177781f8","title":"Butter chicken","intro":"Indisk butter chicken med yoghurtmarinerad, ugnsgrillad kyckling i krämig tomat- och gräddsås, från Dennis Prescotts Eat Delicious (Epicurious).","plan":"Marinering minst 12 h (gärna natten över) + aktiv tillagning ca 1 h","groups":[{"name":"Kyckling","items":[["900 g","benfri, skinnfri kycklingfilé"],["1 msk","färskpressad citronsaft"],["1 tsk","kashmirisk chilipulver (gochu garu)"],["2½ dl","naturell yoghurt"],["1 tsk","malen gurkmeja"],["1 tsk","garam masala"],["3","vitlöksklyftor, finhackade"],["1 msk","riven färsk ingefära"],["1 msk","solros- eller rapsolja"],["1 tsk","havssalt"],["30 g","smör, smält"]]},{"name":"Curry","items":[["55 g","smör"],["2","hela kryddnejlikor"],["4","gröna kardemummakapslar"],["1","svart kardemummakapsel"],["1","bit kanelstång (ca 5 cm)"],["8","vitlöksklyftor, finhackade"],["1 msk","finhackad färsk ingefära"],["½ tsk","bockhornsklöverfrön"],["1–2","röda chili, tärnade"],["4 msk","tomatpuré"],["1","burk krossade tomater (ca 800 g)"],["1 tsk","kashmirisk chilipulver"],["7 dl","kycklingbuljong"],["1 tsk","havssalt"],["1 msk","äkta lönnsirap"],["1 msk","torkade krossade bockhornsklöverblad, kasuri methi (finns hos välsorterade kryddaffärer eller online)"],["2½ dl","vispgrädde"],["1 msk","garam masala"]]},{"name":"Till servering","items":[["2–3 msk","vispgrädde, till garnering"],["","Färsk koriander"],["","Skivad röd chili (valfritt)"],["","Ris eller naan"]]}],"method":[{"name":"Kyckling — förbered kvällen innan","steps":["Skär kycklingen i ca 2,5 cm bitar och blanda med citronsaften och chilipulvret. Lägg i en form och ställ i kylen 20 minuter.","Blanda yoghurt, gurkmeja, garam masala, vitlök, ingefära, olja och salt i en skål. Massera in marinaden i kycklingen, täck och låt stå i kylen över natten eller minst 12 timmar."]},{"name":"Kyckling — tillagning","steps":["Sätt ugnen på 200°C.","Blötlägg 10–12 bambuspett i kallt vatten i ca 20 minuter.","Trä kycklingen på spetten och lägg på ett galler över en plåt. Grilla i ugnen 12 minuter, vänd halvvägs, tills köttsaften är klar och kycklingen genomstekt. Pensla med det smälta smöret och ställ åt sidan."]},{"name":"Curry — starta medan kycklingen är i ugnen","steps":["Smält smöret i en stor tjockbottnad gryta på medelvärme. Tillsätt kryddnejlikor, kardemummakapslar och kanelstång och fräs 2–3 minuter tills det doftar. Rör i vitlök, ingefära, bockhornsklöverfrön, chili och tomatpuré och fräs 2 minuter under omrörning.","Rör i de krossade tomaterna och chilipulvret och låt koka under flitig omrörning så att såsen inte fastnar, ca 20 minuter.","Ta från värmen och mixa såsen slät i vitamixen. Häll tillbaka och sätt på medelvärme, rör i buljongen och saltet, koka upp och låt sjuda ca 15 minuter tills såsen börjar tjockna.","Rör ner den grillade kycklingen i såsen tillsammans med lönnsirapen och de torkade bockhornsklöverbladen. Lägg på lock och koka 8 minuter.","Sänk till medel–låg värme, rör i grädden och garam masalan och låt sjuda en sista gång i 5 minuter.","Toppa varje portion med en skvätt grädde, färsk koriander och skivad röd chili efter smak. Servera med ris eller naan."]}],"notes":[]},{"id":"3e8e56f59722805db9b0dc43e1c6bdf9","notion":"https://app.notion.com/p/3e8e56f59722805db9b0dc43e1c6bdf9","title":"Palak paneer (halloumi)","intro":"Mild och snabblagad palak paneer från ICA med halloumi i krämig grädd- och spenatsås med garam masala, vitlök, ingefära och tomat. 4 portioner.","plan":"","groups":[{"name":null,"items":[["4 port","ris"],["1","blomkålshuvud"],["1","gul lök eller schalottenlök"],["2","vitlöksklyftor"],["2","tomater"],["2 msk","riven ingefära"],["3 msk","olivolja"],["2 msk","tomatpuré"],["1 msk","garam masala"],["390 g","krossade tomater"],["1 dl","vatten"],["2 dl","vispgrädde"],["1","grönsaksbuljongtärning"],["200 g","färsk spenat"],["400 g","halloumi eller grillost"],["2 krm","salt"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 225C","Dela blomkålshuvudet i små buketter och ringla olivolja och salt över på en plåt. Rosta i ugnen i ca 30 min.","Koka riset.","Skala lök och vitlök. Skär löken och tomaterna i skivor, vitlöken i tunna skivor och riv ingefäran fint.","Hetta upp hälften av olivoljan i en stekgryta eller kastrull. Fräs lök och tomarpuré i 2 min. Därefter i med vitlök, ingefära och garam masala i 2 min.","Tillsätt tomater, krossade tomater, vatten, grädde och smulad buljongtärning. Låt sjuda 6–7 minuter. Vänd ner spenaten.","Skär osten i tärningar (och stek dem gyllene i resten av olivoljan i en stekpanna).","Blanda ner osten i grytan, smaka av med salt och servera med ris och blomkål."]}],"notes":[]},{"id":"26ae56f5972280d3a207dceacaab08f3","notion":"https://app.notion.com/p/26ae56f5972280d3a207dceacaab08f3","title":"Rice n’ Beans","intro":"","plan":"","groups":[],"method":[],"notes":[{"heading":null,"lines":["0,5L torra svarta bönor","(Se så alla är fina/bra, skölj alla)","1L vatten","I kylen över natten"]},{"heading":null,"lines":["2L vatten","Koka upp","Häll i bönorna","1,5 delade gullökar","4 klyftor lite smashade vitlök","4 Lagerblad","4 citronmålla (epazote) (annars tre fyra koriander kvistar)"]},{"heading":null,"lines":["Ska alltid ha tillräckligt vatten","Blanda försiktigt ibland","Lätt o krossa en böna, klar.","Ta bort allt som inte är bönorna."]},{"heading":null,"lines":["Sofritto:","Olja","1 Hackad gullök (Eller halv)","Salt","Ganska låg värme","Alla bönor","Lite av vätskan","Sjuda en stund"]},{"heading":null,"lines":["Riset!","Tomat på burk 1st","1/4 msk kummin","Halv lök","2 klyftor vitlök","En del salt","Kycklingbuljong 4dl","Sås/buljong. I tjocklek. Växla tomat/buljong för rätt konsistens."]},{"heading":null,"lines":["Long-grain rice.","Tvätta riset till klart.","Stek riset på medium i olja.","Ska bli brynt.","Sen addera hälften eller så av tomatmixen.","Sen sjuda på låg värme.","Majs, gröna ärtor, hackad morot, serrano chile på (koriander).","Låta stå med lock i 12-13 min.","Låt sen stå en stund för o sätta sig lite."]},{"heading":null,"lines":["Platea.","Queso fresco på bönorna. Som mild feta."]}]},{"id":"2dee56f5972280c2b0eacda42b023340","notion":"https://app.notion.com/p/2dee56f5972280c2b0eacda42b023340","title":"Corn Wheat Tortillas","intro":"För 12 st små tortillas eller 6st medelstora.","plan":"","groups":[{"name":null,"items":[["1dl","vetemjöl"],["1dl","majsmöl"],["1krm","salt"],["1-2msk","olivolja"],["1dl","kokande vatten"],["","vetemjöl i kavling"]]}],"method":[{"name":null,"steps":["Blanda vetemjöl, majsmjöl och salt i en bunke.","Tillsätt olivolja för att få det som en smulig blandning. (Kan behövas mer olivolja).","Häll i det kokande vattnet och vänd med slickepott eller träslev till en jämn deg.","Dela i 6 eller 12 delar, beroende på önskad storlek.","Förbered en lite fuktig kökshandduk i en rund form.","Sätt en eller två stekpannor på värmning. De ska vara riktigt varma på “6.” eller “7”.","Kavla ut degbitarna till runda tortillas och stek i cirka 1 min per sida.","Lägg dem därefter i kökshandduken inför servering."]}],"notes":[]},{"id":"2bbe56f59722805593edff631bb0713a","notion":"https://app.notion.com/p/2bbe56f59722805593edff631bb0713a","title":"Slow Pork with Leek","intro":"Boneless ribs with a splash of white wine and tons of leek, served with mash.","plan":"","groups":[{"name":null,"items":[["1kg","benfria revbensspjäll"],["","En bunke med purjolök"],["1-2dl","vitt vin"],["2","klyftor vitlök"],["","Cirka 0,5-1dl grädde"],["","Cirka 0,5L vatten (gå på känsla/visuellt i grytan, ska inte täcka, men minst 50% typ)."]]}],"method":[{"name":null,"steps":["Skär köttet i bitar. Salta generöst och låt vara i minst 10 min, gärna någon timme eller kylen över natten. Men se till att det blir rumstemp inför tillagning.","Förbered under tiden purjolök som kan ligga och dra i en skål med kallt vatten en stund (några minuter).","Hacka därefter i ett några millimeters skivor.","Slå till vitlöksklyftorna.","Sätt på ugnen på 175 C.","Värm en traktör eller kastrull att bryna i och tillaga allt i.","Torka rent köttet med hushållspapper så att det är torrt.","Bryn köttet på hög värme. Lägg därefter över på tallrik.","Sänk värmen och fräs typ 70% av purjolöken i samma panna. Lägg i vitlöken efter en stund.","Häll i vinet, därefter tillbaka med köttet.","Häll i vattnet (gärna förkokat) och se till att det är uppe i temp.","Ställ in kärlet med lock i 1h i ugnen, på 175 C.","Därefter ner med resten av löken och in igen i 15 min på 200 C.","Sist, ner med grädden och blanda runt så det som fått färg hamnar uppochner (lite grovt). Låt detta gå 15 min till på 200 C.","Nu kan den smakas av med salt (och ev något annat för balans. Behövdes inte förra gången).","Servera med potatismos."]}],"notes":[]},{"id":"35de56f597228087b211fbcfaaafacce","notion":"https://app.notion.com/p/35de56f597228087b211fbcfaaafacce","title":"Cocoa-Blackened Chicken med Stenfrukter","intro":"Kycklinglår dammade i kakao och Old Bay som svartnar vackert under tillagning — serveras på en frisk salsa av stenfrukter, mynta och lime. Recept från Bon Appétit / Epicurious.","plan":"","groups":[{"name":null,"items":[["900 g","skinless kycklinglår utan ben (4–6 st), torkade"],["15 g","osötat kakaopulver, gärna Dutch-process"],["30 g","Old Bay eller Creole-krydda (t.ex. Tony Chachere’s eller Zatarain’s)"],["90 ml","olivolja, delat"],["3","vitlöksklyftor, fint rivna"],["","Saft av 3 lime"],["15 g","honung"],["2","schalottenlökar, tunt skivade i ringar"],["680 g","blandade stenfrukter (persikor, nektariner och/eller plommon, aprikoser), skivade"],["15 g","färska myntablad"],["","Salt och nymalen svartpeppar"]]}],"method":[{"name":null,"steps":["Blanda kakaopulver och Old Bay i en liten skål. Gnid in kycklingstyckena runtom med kryddblandningen och krydda med salt.","Hetta upp 45 ml av olivoljan i en stor stekpanna på medelhög till hög värme. Lägg ner kycklingen i ett lager och stek under vändning tills den är svartnad i fläckar, genomstekt och en termometer visar 74°C i tjockaste delen, totalt 10–14 minuter beroende på tjocklek. Lyft upp och lägg på en tallrik.","Vispa ihop limesaft, vitlök, honung, salt, peppar och resterande 45 ml olivolja i en stor skål. Tillsätt schalottenlöken, stenfrukterna och myntan och vänd försiktigt runt. Smaka av och justera salt och peppar.","Lägg upp fruktsalladen på ett fat. Skiva kycklingen och arrangera ovanpå. Häll över eventuellt kvarvarande dressing från skålen."]}],"notes":[{"heading":null,"lines":["(+extra bulgur/quinoa och kanske feta för matighet)"]}]},{"id":"38ae56f5972280ffa045f38253a8f247","notion":"https://app.notion.com/p/38ae56f5972280ffa045f38253a8f247","title":"Cesarsallad","intro":"Klassisk caesarsallad från Coop med romansallad, parmesan och kyckling, toppad med en krämig caesardressing.","plan":"","groups":[{"name":"Sallad","items":[["140 g","bacon, strimlat"],["1","romansalladshuvuden"],["500 g","kycklinglårfilé"],["1 dl","hyvlad parmesan"],["1/2","rödlök i skivor"]]},{"name":"Caesardressing","items":[["1","ägg"],["6","sardellfiléer (alt. 1 tsk worcestershiresås + 1 tsk fisksås)"],["1","vitlöksklyfta, finriven"],["1 msk","vitvinsvinäger"],["1 tsk","dijonsenap"],["1 tsk","worcestershiresås"],["2 dl","neutral olja"],["2 dl","finriven parmesan"],["","salt och svartpeppar"]]},{"name":"Krutonger","items":[["1","skiva vitt bröd, tärnat"],["1","vitlöksklyfta, finriven"],["2 msk","olivolja"]]}],"method":[{"name":null,"steps":["Salta och peppra kycklingfiléerna och stek i olja tills de fått fin färg och har en innertemperatur på 70 grader, cirka 15 minuter.","Gör dressingen. Mixa ägg, sardeller, vitlök, vinäger, senap, worcestershiresås och olja till en majonnäs, i matberedare eller med en mixerstav. Rör ner parmesanen och smaka av med salt och peppar.","Blanda brödtärningar, vitlök och olja på en plåt med bakplåtspapper. Rosta mitt i ugnen på 200°, ca 5-7 min. Stek baconet knaprigt.","Bryt salladen i bitar. Skiva kycklingen. Hacka rödlöken. Blanda sallad och kyckling med hälften av dressingen. Toppa med bacon och krutonger och servera med resten av dressingen."]}],"notes":[]},{"id":"2d8e56f59722807cacd5d21424ae702b","notion":"https://app.notion.com/p/2d8e56f59722807cacd5d21424ae702b","title":"Pulled Pork TK","intro":"","plan":"","groups":[{"name":"Kött","items":[["1 kg","Picnicbog"],["","Salt"]]},{"name":"Kryddblandning","items":[["2 msk","paprika"],["1 msk","malen spiskummin"],["1-2 tsk","liquid smoke"],["1 tsk","cayenne"],["4msk","mörkt muscovadosocker"],["3dl","vatten"],["4tsk","äppelcidervinäger"],["1 dl","bbq-sås, ex Sweet Baby Rays"]]},{"name":"V1 (helt ok) – Kött","items":[["1 kg","fläskkarré (Tog picnincbog första gången, blev lite torrt)"],["","Salt"]]},{"name":"V1 (helt ok) – Kryddblandning","items":[["1 msk","malen spiskummin."],["1 msk","rökt paprikapulver/chipotle."],["1 tsk","chiliflakes (Skippa om du tar chipotle)."],["0,5 tsk","ancho chilipulver"],["1 msk","mörkt muscovadosocker"],["3","stora vitlöksklyftor"],["33 cl","mörk öl, ex porter"],["1 dl","bbq-sås, ex Sweet Baby Rays"]]}],"method":[{"name":null,"steps":["Låt köttet vara helt (en stor bit).","Salta rejält och låt dra och komma till rumstemp.","Blanda ihop kryddblandningen. Alla ingredienser där i en behållare.","Torka av köttet och bryn i smör i TK.","Häll över kryddblandningen och sätt på 1,5h, high i TK.","Släpp tryck (och låt naturligt släppa tryck om tid finns).","Lyft ur köttet och låt vila i några minuter. Reducera eventuellt såsen. Smaka av med salt och äppelcidervinäger.","Dra isär köttet och servera."]},{"name":"V1 (helt ok)","steps":["Skär köttet i medelstora bitar (för att bevara längd när det blir pulled pork).","Salta rejält och låt dra och komma till rumstemp.","Blanda ihop kryddblandningen. Alla ingredienser där i en behållare.","Torka av köttet och bryn i smör i TK.","Häll över kryddblandningen och sätt på 75-90 min, high i TK.","Släpp tryck och sätt på spisen för att reducera och smaka av. (Inte för mycket).","Dra isär köttet och servera."]}],"notes":[{"heading":null,"lines":["Tillbehör: Coleslaw"]},{"heading":"V1 (helt ok)","lines":["Tillbehör: Picklad rödlök, coleslaw, refried beans."]}]},{"id":"2d8e56f5972280a9afb8d7b01e9ca9f2","notion":"https://app.notion.com/p/2d8e56f5972280a9afb8d7b01e9ca9f2","title":"Coleslaw","intro":"","plan":"","groups":[{"name":"Bas","items":[["250g","vitkål"],["2","små morötter."],["1","liten rödlök"]]},{"name":"Dressing","items":[["1dl","creme fraiche"],["1/2dl","majonnäs"],["1tsk","fransk senap, dijon"],["1tsk","socker"],["1/2tsk","salt"],["1 krm","svartpeppar"]]}],"method":[{"name":null,"steps":["Ta fram mandolin och ställ in lagom tunnt.","Skiva vitkålen och rödlöken.","Byt blad till finaste julienne och skär de två morötterna så mycket som går (två halvor blir kvar, som kan ätas direkt eller sparas).","Rör samman dressingen, alla ingredienser. Smaka av med salt och socker.","Blanda allt och låt gärna stå kallt en stund innan servering."]}],"notes":[]},{"id":"251e56f5972280989ee6f2757b37568b","notion":"https://app.notion.com/p/251e56f5972280989ee6f2757b37568b","title":"Super Simple Carbonara","intro":"Snabb fulcarbonara för enkel o lite go middag eller lunch.","plan":"","groups":[{"name":null,"items":[["","Pasta för 2"],["","Bacon 1pk"],["","Ägg 2st"],["","(Parmesan)"],["","Salt"]]}],"method":[{"name":null,"steps":["Koka upp vatten och salt.","Skär bacon och stek.","Blanda kokt pasta med en äggula och ett helt ägg.","Blanda med bacon och riven parmesan."]}],"notes":[]},{"id":"2b9e56f5972280c492f0fedd01c06cb9","notion":"https://app.notion.com/p/2b9e56f5972280c492f0fedd01c06cb9","title":"Super Simple Pea Pasta","intro":"","plan":"","groups":[{"name":null,"items":[["","Pasta för 2"],["3dl","frysta ärtor"]]},{"name":"Blanda med","items":[["200g","fetaost (ett paket)"],["","En bunt persilja"],["","Zest från 1/2 citron"],["","Svartpeppar"],["3msk","olivolja"],["1-2","finhackade vitlöksklyftor"]]}],"method":[{"name":null,"steps":["Koka upp vatten och salt.","Gör blandingen med allt utom fetaosten först, lägg i den sist.","Koka pastan och rör ihop med blandningen. (Spara pastavatten att blanda i för rätt konsistens)"]}],"notes":[]},{"id":"373e56f597228029af44d7aae48f77ab","notion":"https://app.notion.com/p/373e56f597228029af44d7aae48f77ab","title":"Kyckling Alfredo i panna","intro":"Krämig kyckling och pasta som tillagas i en och samma panna, från Epicurious.","plan":"","groups":[{"name":null,"items":[["680 g","benfria, skinnfria kycklingfiléer, skurna i ca 2,5 cm bitar"],["","Salt och nymalen svartpeppar"],["30 g","osaltat smör"],["1 tsk","finhackad vitlök (ca 1 klyfta)"],["950 ml","kycklingbuljong, gärna med låg salthalt"],["450 g","penne rigate eller ziti"],["360 ml","vispgrädde (eller matlagningsgrädde), uppvärmd"],["90 g","nyriven parmesan, plus extra till servering"],["15 g","hackad färsk bladpersilja (valfritt)"]]}],"method":[{"name":null,"steps":["Krydda kycklingbitarna med salt och peppar.","Smält smöret i en stor panna på medelhög–hög värme. Bryn kycklingen, i omgångar vid behov, tills den fått fin färg på utsidan men fortfarande är något rosa inuti, ca 4 minuter. Lyft upp och lägg åt sidan.","Rengör inte pannan — de brynta bitarna i botten ger smak. Tillsätt vitlöken och fräs på medelvärme tills den doftar, ca 30 sekunder.","Höj värmen, häll i kycklingbuljongen och skrapa loss bottensatsen. Låt koka upp, sänk till medelvärme och låt sjuda 5 minuter.","Tillsätt pastan, rör om och låt sjuda tills pastan börjar mjukna, ca 8 minuter.","Rör ner den uppvärmda grädden samt kycklingen med eventuell köttsaft. Lägg på lock och låt sjuda under omrörning tills pastan är mör, det mesta av vätskan absorberats och kycklingen är genomstekt, ca 4 minuter till.","Rör ner parmesanen och persiljan. Smaka av med salt och peppar. Servera med extra parmesan."]}],"notes":[]},{"id":"35de56f59722808897d3eae3324ba7f2","notion":"https://app.notion.com/p/35de56f59722808897d3eae3324ba7f2","title":"Instant Pot Italiensk Kikärtsgryta med Pesto","intro":"Kikärtor tillagade under tryck med morötter, tomater och grönsaksbuljongen — serveras med en klick pesto och riven parmesan. Recept från Epicurious.","plan":"","groups":[{"name":null,"items":[["450 g","torkade kikärtor"],["1 liter","vatten"],["15 g","salt (till blötläggning), plus mer till matlagning"],["30 ml","olivolja"],["1","liten gul lök, grovhackad"],["2","morötter, skalade och hackade"],["1","burk hela eller hackade tomater (ca 400 g), med spad"],["950 ml","grönsaksbuljong"],["60 g","riven parmesan, plus mer till servering"],["1","burk färdigköpt basilikpesto (ca 190 g)"]]}],"method":[{"name":null,"steps":["Lägg kikärtor i blöt i kallt vatten med 15 g salt i 8–24 timmar. Häll av och skölj.","Hetta upp olivoljan i Instant Pot på Sauté-läge. Tillsätt löken med ett par nypor salt och fräs under omrörning tills mjuk och lätt gyllene, 5–8 minuter.","Tillsätt kikärtor, morötter, tomater med spad och grönsaksbuljongen. Lås på locket och kör på högt tryck i 10 minuter. Släpp ut trycket manuellt.","Rör ner parmesanen. För en tjockare gryta, ta upp en kopp av grytan, mixa den slät och rör tillbaka i grytan. Smaka av med salt och peppar.","Fördela i djupa tallrikar. Klicka på pesto och strö över extra parmesan."]}],"notes":[]},{"id":"35de56f597228098b287e436587ade25","notion":"https://app.notion.com/p/35de56f597228098b287e436587ade25","title":"Linsbolognese","intro":"Färdigmarinerade linser ger kropp, protein och djup smak åt denna pastasås. Hemligheten är att röra ner en del i såsen och strö resten över direkt vid servering — för textur och smakkontrast. Baconet är valfritt men rekommenderas. Recept från Epicurious.","plan":"","groups":[{"name":"Marinerade linser (görs i förväg)","items":[["400 g","torkade linser (t.ex. gröna eller svarta Puy-linser)"],["60 ml","olivolja"],["30 ml","rödvinsvinäger"],["","Salt och nymalen svartpeppar"]]},{"name":"Bolognese","items":[["30 g","olivolja"],["55 g","bacon eller pancetta, finhackat (valfritt)"],["1","stor gul lök, finhackad"],["4","vitlöksklyftor, finhackade"],["30 g","harissapasta eller tomatpuré"],["120 ml","rödvin eller torrt vitt vin"],["1","burk hela eller hackade tomater (ca 800 g)"],["540 g","marinerade linser (se ovan), delat"],["","Salt och nymalen svartpeppar"],["450 g","torkad pasta (valfri sort)"],["30 g","osaltat smör, skuret i bitar"],["","Fint riven parmesan till servering (valfritt)"]]}],"method":[{"name":null,"steps":["Koka linserna: täck med rikligt med vatten, koka upp och sjud 20–25 minuter tills de är mjuka men fortfarande fasta. Häll av och låt svalna något. Blanda med olivolja, rödvinsvinäger, salt och peppar. Låt marinera minst 30 minuter (eller förbered dagen innan).","Hetta upp olivoljan i en stor tjockbottnad kastrull eller gryta på medelhög värme. Fräs baconet (om du använder) tills lätt brynt, ca 3 minuter. Tillsätt löken och fräs under omrörning tills mjuk och lätt gyllene, 8–10 minuter.","Rör ner vitlöken och harissapasta/tomatpuré och fräs ytterligare 2 minuter tills pastan mörknar något och karamelliseras.","Häll i vinet och skrapa upp stekskorpan från botten. Koka tills vinet reducerats till hälften, ca 3 minuter.","Tillsätt tomaterna och krossa dem grovt med en slev. Rör ner hälften av de marinerade linserna (ca 270 g). Sjud på låg värme under omrörning ibland tills såsen tjocknat, ca 30 minuter. Smaka av med salt och peppar.","Koka pastan i rikligt med saltat vatten tills al dente. Spara 240 ml pastakok innan du häller av.","Rör ner smöret i såsen bit för bit. Blanda ner den avrunna pastan och tillsätt lite pastakok vid behov för att såsen ska klä nudlarna.","Fördela i djupa tallrikar och toppa med de resterande marinerade linserna (ca 270 g) och riven parmesan."]}],"notes":[]},{"id":"256e56f59722802cb1c2f242db9d6fd3","notion":"https://app.notion.com/p/256e56f59722802cb1c2f242db9d6fd3","title":"Klassiska bullar","intro":"Favorit (coops).","plan":"1,5h för degen + 1h formning och jäsning på plåt + 0,5h gräddning = 3h","groups":[{"name":"Degen","items":[["780g","mjöl"],["0,5L","3% mjölk"],["14g (en påse)","torrjäst"],["90g (1dl)","strösocker"],["10g (1msk)","mortlade/finkrossade kardemummakärnor"],["6g (1tsk)","salt"],["150g","smör, rumstemp"]]},{"name":"Fyllning: För kanelbullar","items":[["150g","smör, rumstemp"],["90g (1dl)","strösocker"],["15g (2msk)","malen kanel"]]},{"name":"Fyllning: För vaniljbullar","items":[["150g","smör, rumstemp."],["90g (1dl)","strösocker."],["30g (0,5dl)","vaniljsocker, alt. 2 vaniljstänger."]]},{"name":"Pensling innan ugn","items":[["1","ägg, lätt vispat"]]},{"name":"Pensling efter ugn","items":[["1dl","sockerlag = 0,5dl strösocker + 0,5dl kokande vatten blandat."]]}],"method":[{"name":null,"steps":["Blanda mjöl och jäst i en bunke och låt stå 10 min.","Värm mjölken till 37°.","Rör ner socker, kardemumma, salt och mjölk i mjölet. Klicka i smöret.","Arbeta till en deg ca 5 min i maskin eller 10 min för hand.","Låt degen jäsa under bakduk ca 1 tim."]},{"name":"Knutar","steps":["Sätt ugnen (med bakstål), på 225°C.","Rör ihop ingredienserna till fyllningen.","Förbered 2-3 plåtar med bakplåtspapper.","Ta upp degen på mjölat bakbord. Dela den i två delar och kavla ut varje del till en rektangel, ca 25x50 cm.","Bred på fyllningen.","Vik rektanglarna en gång på längden och skär ut 8 degremsor ur varje rektangel.","Tvinna varje degremsa och forma den till en lös knut. Lägg på plåtarna.","Låt varje plåt jäsa i cirka 30 min."]},{"name":"Gräddning","steps":["Pensla bullarna med det uppvispade ägget.","Grädda i cirka 12 minuter.","Ta ut och pensla med sockerlagen.","Låt svalna på galler en stund (cirka 10-30 min) och in i frysen till sist."]}],"notes":[]},{"id":"2b6e56f5972280e78d89e8e5adb48749","notion":"https://app.notion.com/p/2b6e56f5972280e78d89e8e5adb48749","title":"Surdegsfrallor","intro":"Klassiska snabba och enkla surdegsfrallor.","plan":"","groups":[{"name":null,"items":[["450g","mjöl"],["150g","egenmalt"],["300g","vete special"],["360g","vatten"],["100g","surdeg"],["8g","salt"]]}],"method":[{"name":null,"steps":["Blanda allt utom salt.","30-60 min autolys.","I med salt och kör maskin eller S\u0026amp;F tills degen är go.","Jäs i rumstemp typ 2-3h, med nån fold inemellan.","Sen in i kylen öven natten.","Nu ska de bakas av.","Sätt ugnen på 250 C.","Ut på mjölat bord och dela upp i ca 8 frallor, o lägg över på plåt med bakplåtspapper.","Baka i ca 15 min, tills fina.","Lägg på galler, klart."]}],"notes":[]},{"id":"2bbe56f597228082ae4df751df460344","notion":"https://app.notion.com/p/2bbe56f597228082ae4df751df460344","title":"Lussebullar","intro":"Klassiska lussebullar, med fördeg och lite småfix dagen innan.","plan":"","groups":[{"name":"Fördeg","items":[["0,5L","mjölk"],["1-1,5g","saffran (ihop med lite socker och 1,5msk rom)"],["50g","jäst (blå)"],["600g","vetemjöl special"],["1msk","socker"]]},{"name":"Dag 2 – Deg","items":[["ca 400g","vetemjöl special"],["200g","smör rumstemp"],["1","ägg i rumstemp"],["200g","socker"],["10g","salt"]]},{"name":"Utöver degen","items":[["1","ägg + 2msk vatten och en nypa salt, stavmixat, till pensling efter gräddning."],["3-4msk","russin + ca 1 dl glögg."]]}],"method":[{"name":null,"steps":["Först av allt, gör saffransblandningen i förväg."]},{"name":"Dag 1 – Fördeg","steps":["Rör ut jästen med saffransblandningen, sockret och lite av mjölken.","Tillsätt resten av mjölken och mjölet till fördegen (600 g). Rör i någon minut.","Låt helst jäsa över natten i kylen. Tänk på att degen expanderar, så ha gärna en ganska stor bunke.","Ta ut smör och ägg ur kylen så att de är rumstempererade till nästa dag."]},{"name":"Dag 2","steps":["Koka upp glögg, dra åt sidan och lägg i russinen.","Arbeta in smör, mjöl, ägg och socker i fördegen, men häll i lite i taget av mjölet. Degen ska kännas kladdig men släppa någorlunda från kanterna. Det är inte säkert att allt mjöl behövs. Tillsätt saltet i slutet av knådningen.","Knåda degen i minst 20-30 minuter för hand eller 15-20 minuter i maskin. Kör långsammare i början.","Låt degen vila i 30 minuter under plast eller handduk.","Häll upp på bakbord, använd gärna degskrapa. Dela i tre lika stora degklumpar, därefter 10st bullar per degklump, totalt blir det 30st bullar. Forma till lussekatter.","Garnera med russinen genom att trycka ner dem en bit. Låt jäsa övertäckta i minst 1 timme till dubbel storlek. Tid beror på rumstemp.","Grädda i ca 6-8 minuter i nedre delen av ugnen på 220 grader över- och undervärme. Temperaturen kan skilja från ugn till ugn så håll gärna koll på bullarna. Använd gärna bakstål. (Förvärm i så fall i 1h)","Pensla direkt med ägget stavmixat med vatten och en liten nypa salt. Frys in så snart bullarna har kallnat."]}],"notes":[{"heading":"Generella tips","lines":["Använd rumstemp smör och ägg.","Blöt russinen i glögg eller annat innan.","Mortla saffran med socker och blanda med t.ex. rom dagen innan (eller 30 min innan). (Kan stå i månader).","Knåda degen länge.","Täck helst degen tätt med t.ex. plastfolie.","Flexibel jästid utifrån rumstemp.","Pensla efter gräddning."]}]},{"id":"334e56f597228063a7ccc02ea470a391","notion":"https://app.notion.com/p/334e56f597228063a7ccc02ea470a391","title":"Klassiska hamburgerbröd","intro":"Hybrid mellan brioche och enkelt bröd. Går att baka i förväg och frysa.","plan":"1h för degen + 1h forma och jäsa + 30 min gräddning och svalna = 2,5h","groups":[{"name":null,"items":[["7 g","torrjäst"],["25 g","smör"],["250 g","mjölk"],["½ tsk","salt"],["½ tsk","strösocker"],["330 g","vetemjöl special"],["1","ägg"],["","Sesamfrön"]]}],"method":[{"name":null,"steps":["Smula jästen i en bunke. Smält smöret i en kastrull, häll i mjölken och värm till 37°C. Häll vätskan över jästen och rör tills den löst sig.","Tillsätt salt, socker, eventuellt gurkmeja och nästan allt mjöl. Arbeta degen 10 minuter i maskin eller 15 minuter för hand.","Låt jäsa under bakduk i 40 minuter.","Knåda degen lätt med resten av mjölet. Dela i 6 delar, rulla till bollar och lägg på bakpappersklädd plåt. Tryck till lätt så de plattas lite. Täck med bakduk och låt jäsa 30 minuter.","Sätt ugnen på 225°C. Pensla bröden med uppvispat ägg och strö över sesamfrön.","Grädda mitt i ugnen ca 10 minuter tills de fått fin färg. Låt svalna på galler innan de delas."]}],"notes":[]},{"id":"2bbe56f5972280b1a5b1ff972f566fae","notion":"https://app.notion.com/p/2bbe56f5972280b1a5b1ff972f566fae","title":"Glass – No Churn","intro":"Basrecept på glass som görs i vitamixen utan glassmaskin, med 6h i frysen.","plan":"","groups":[{"name":null,"items":[["2 cups","grädde"],["1 cup","sötad kondenserad mjölk"],["1/4 cup","sirap"],["1/4 cup","mjölk"],["2 msk","socker"],["1 tsk","vanilj"],["1/4 tsk","salt"]]}],"method":[{"name":null,"steps":["Kör grädden 10-20 sek, tills fluffig/håller formen.","Ner med den sötade kondenserade mjölken, sirapen, mjölken, sockret, vaniljen, saltet. (Allt resterande alltså). Blanda det innan du mixar, så att det är jämnt fördelat (men såklart inte perfekt mixat). Nu kan du mixa i typ 20 sek, se till att det inte är något som fastnat uppe eller så.","Ner i en brödform, lägg plastfolie helt täckande på glassens yta. Den ska frysas så snabbt som möjligt nu.","6h i frysen nu och därefter redo att servera."]}],"notes":[]},{"id":"2d8e56f59722804ba3c2e698fdab230b","notion":"https://app.notion.com/p/2d8e56f59722804ba3c2e698fdab230b","title":"Fransk vaniljglass – Crème Anglaise","intro":"","plan":"","groups":[{"name":null,"items":[["0,5-1","vaniljstång"],["250g","mjölk"],["250g","grädde"],["25g","honung"],["6st","äggulor"],["125g","socker"]]}],"method":[{"name":"Steg 1 – Crème Anglaise","steps":["Skrapa och lägg ner vaniljstång i kastrull á minst 1L.","Häll i:\nMjölken\nGrädden\nHonungen","Separera äggulorna från vitorna och blanda gulorna med sockret. Vispa till fluffigt/vispat.","Koka upp gräddblandningen.","Blanching: Ta lite av gräddblandningen och vispa i lite i taget i äggulorna. Bara någon dl.","Häll därefter i de vispade äggulorna tillbaka i gräddblandningen (i kastrullen).","Få försiktigt upp hela till 83-85 C. Blanda hela tiden. Håll på denna temp tills det tjocknat. Dra sedan åt sidan för att avstanna upphettning.","Kyl ner kastrullen i ett vattenbad i diskhon, eller isvatten i skål.","Sätt glassmaskinen på pre-cool, medan du får ner tempen på kastrullen."]},{"name":"Steg 2 – Churn","steps":["Häll i din kalla Creme Anglaise i glassmaskinen.","Gör till “Ice Cream” någon av konsistenserna. Tog 50-60 min första gången.","Färdig att äta. Eller stjälp ner i behållare och in i frysen och ta fram när som."]}],"notes":[]},{"id":"3d9e56f5972280bb997fdfde6e80562f","notion":"https://app.notion.com/p/3d9e56f5972280bb997fdfde6e80562f","title":"Kaffeglass","intro":"Följ receptet för fransk vaniljglass nedan och addera 5g snabbkaffe efter créme anglaise är gjord och är varm, men 80C max då just, så precis innan du kyler ner blandningen.","plan":"","groups":[],"method":[],"notes":[]},{"id":"2dbe56f5972280a4b3c7e41a1f144645","notion":"https://app.notion.com/p/2dbe56f5972280a4b3c7e41a1f144645","title":"Salted Caramel Glass","intro":"","plan":"","groups":[{"name":"Crème anglais","items":[["1,5 dl","grädde 40%"],["5dl","mjölk 3%"],["125g + 25g","socker"],["0,5dl","vatten."],["1","vaniljstång"],["","Salt"],["5","äggulor"]]}],"method":[{"name":"Steg 1 – Caramel och prep","steps":["Två kastruller behövs.","I den mindre kastrullen häller du i grädden och vaniljen, skrapad och hela stången.","Få upp grädden att precis börja koka (eller nära) och låt vara på svag värme så den håller sig varm.","Häll 125g socker i den större kastrullen och tillsätt 0,5dl vatten.","Sätt värmen relativt högt på kastrullen med sockret. Så fort den börjar få minsta lilla färg så sänker du till medium värme.","Låt karamellisera tills den är djup gyllene (brun).","Så fort den nått rätt färg så häller du ner gräddblandningen i karamellen (det kommer bubbla rejält). Men detta kyler ner karamellen och avstannar karamelliseringen.","Ta av blandingen nu från plattan och låt svalna något."]},{"name":"Steg 2 – Crème Anglaise","steps":["Blanching: Separera äggulorna från vitorna och blanda gulorna med 25g socker. Vispa till fluffigt/vispat.","Häll nu i mjölken och få upp temperaturen så det ångar lite (samma kastrull som karamellen är i). Det ska inte koka (då vi senare inte vill gå över 85 C).","Tempering: Ta lite av gräddblandningen och vispa i lite i taget i äggulorna. Bara någon dl.","Häll därefter i de vispade äggulorna tillbaka i gräddblandningen (i kastrullen).","Få försiktigt upp hela till 85 C. Blanda hela tiden. Dra sedan åt sidan för att avstanna upphettning. Håll i ett par minuter på 83-85 C tills det tjocknat.","Kyl ner kastrullen i ett vattenbad i diskhon, eller isvatten i skål. (Ställ i kylen i 4-24h)","Sätt glassmaskinen på pre-cool, medan du får ner tempen på kastrullen."]},{"name":"Steg 2 – Churn","steps":["Häll i din kalla glassmassa i glassmaskinen.","Gör till “Ice Cream” någon av konsistenserna. Tog 50-60 min första gången.","Färdig att äta. Eller stjälp ner i behållare och in i frysen och ta fram när som."]}],"notes":[{"heading":null,"lines":["(Note: Jättegod. Men känns som att lite mer grädde och lite mindre mjölk hade varit godare). Hade man kunnat göra exakt samma recept men med 50/50 grädde/mjölk? Eller finns det egenskaper här i sockermängd eller annat som gör det sämre?"]}]},{"id":"301e56f59722809fb200d3624b07a485","notion":"https://app.notion.com/p/301e56f59722809fb200d3624b07a485","title":"Hazelnut Ice Cream","intro":"","plan":"","groups":[{"name":null,"items":[["500g","mjölk"],["25g","honung"],["6st","äggulor"],["150g","råsocker eller vanligt strösocker"],["100g","rostade hasselnötter (tog 160g sist, och det blev lite för mäktig/fet smak)."]]}],"method":[{"name":"Steg 1 – Hasselnötsmjölk","steps":["Rosta hasselnötterna om de inte är färdigt. (200 C i fem min, sen bara kolla av med 2 min intervall, kan ta upp till 10-20 min).","Skala hasselnötterna genom att lägga i en kökshandduk och skaka/gnida runt dem i handduken.","Häll sedan all mjölk (500g) i vitamixen och alla hasselnötter och kör i cirka 3 min på max."]},{"name":"Steg 2 – Crème Anglaise","steps":["Häll i en kastrull på minst 1L:\nHasselnötsmjölken\nHonungen","Separera äggulorna från vitorna och blanda gulorna med sockret. Vispa till fluffigt/vispat.","Koka upp mjölkblandningen.","Blanching: Ta lite av gräddblandningen och vispa i lite i taget i äggulorna. Bara någon dl.","Häll därefter i de vispade äggulorna tillbaka i gräddblandningen (i kastrullen).","Få försiktigt upp hela till 83-85 C. Blanda hela tiden. Håll på denna temp tills det tjocknat. Dra sedan åt sidan för att avstanna upphettning.","Kyl ner kastrullen i ett vattenbad i diskhon, eller isvatten i skål.","Sätt glassmaskinen på pre-cool, medan du får ner tempen på kastrullen."]},{"name":"Steg 3 – Churn","steps":["Häll i din kalla glassmassa i glassmaskinen.","Gör till “Ice Cream” någon av konsistenserna. Tog 40 min första gången (då massan var 4 C).","Färdig att äta. Eller stjälp ner i behållare och in i frysen och ta fram när som."]}],"notes":[]},{"id":"2e4e56f59722804f8611e783591d5d34","notion":"https://app.notion.com/p/2e4e56f59722804f8611e783591d5d34","title":"Almond Ice Cream","intro":"","plan":"","groups":[{"name":null,"items":[["500g","mjölk"],["25g","honung"],["6st","äggulor"],["150g","råsocker eller vanligt strösocker"],["100g","rostade mandlar (skala innan du rostar)."]]}],"method":[{"name":"Steg 1 – Mandelmjölk","steps":["Sätt ugnen på 200 C.","Koka upp vatten som kommer täcka mandlarna gott och väl. Häll därefter i de råa mandlarna och koka i cirka 1 min. Skölj därefter i kallt vatten och ploppa ut de med de mot de spetsiga änden, med fingrarna.","Rosta mandlarna. (200 C i fem min, sen bara kolla av med 2 min intervall, kan ta upp till 10-20 min).","Häll sedan hälften av mjölken (250g) i vitamixen och alla mandlar och kör i cirka 3 min på max. Häll sedan resten (250g till) i mixern och kör någon minut tills blandat och finfördelat."]},{"name":"Steg 2 – Crème Anglaise","steps":["Häll i en kastrull på minst 1L:\nMandelmjölken\nHonungen","Separera äggulorna från vitorna och blanda gulorna med sockret. Vispa till fluffigt/vispat.","Koka upp mjölkblandningen.","Blanching: Ta lite av gräddblandningen och vispa i lite i taget i äggulorna. Bara någon dl.","Häll därefter i de vispade äggulorna tillbaka i gräddblandningen (i kastrullen).","Få försiktigt upp hela till 83-85 C. Blanda hela tiden. Håll på denna temp tills det tjocknat. Dra sedan åt sidan för att avstanna upphettning.","Kyl ner kastrullen i ett vattenbad i diskhon, eller isvatten i skål.","Sätt glassmaskinen på pre-cool, medan du får ner tempen på kastrullen."]},{"name":"Steg 3 – Churn","steps":["Häll i den kalla glassmassan i glassmaskinen.","Gör till “Ice Cream” någon av konsistenserna. Tog 40 min första gången (då massan var 4 C).","Färdig att äta. Eller stjälp ner i behållare och in i frysen och ta fram när som."]}],"notes":[]},{"id":"3d8e56f5972280b79f6cc796be6755ee","notion":"https://app.notion.com/p/3d8e56f5972280b79f6cc796be6755ee","title":"Gelato Fior Di Latte","intro":"Enkel gelato med majsstärkelse som stabilisator, av Lidey Heuck. Ger ca 1 liter.","plan":"","groups":[{"name":null,"items":[["475 ml","standardmjölk"],["2 msk","majsstärkelse"],["355 ml","vispgrädde"],["150 g","strösocker"],["¾ tsk","flingsalt"]]}],"method":[{"name":null,"steps":["Vispa ihop 60 ml av mjölken med majsstärkelsen i en skål tills det är slätt.","Häll resterande 415 ml mjölk, grädden, sockret och saltet i en stor kastrull. Låt sjuda på medelvärme och rör då och då tills sockret löst sig.","Vispa långsamt ner majsstärkelseblandningen och låt koka upp till en kraftig sjudning. Koka under omrörning tills smeten precis täcker baksidan av en sked, 3–4 minuter.","Låt svalna till rumstemperatur, täck och kyl i kylskåp tills den är riktigt kall, minst 2 timmar.","Kör smeten i glassmaskin tills den får gelatokonsistens, ungefär som mjukglass.","Skeda över i en form och frys tills den är fast, minst 2 timmar och upp till 3 dagar.","Låt gelaton mjukna 5–10 minuter i rumstemperatur innan servering."]}],"notes":[]},{"id":"3a8e56f5972280b7944de3907e0398dd","notion":"https://app.notion.com/p/3a8e56f5972280b7944de3907e0398dd","title":"Grundsockerlag – till glass","intro":"","plan":"","groups":[{"name":null,"items":[["100g","vatten"],["135g","socker"],["25g","glukossirap"]]}],"method":[{"name":null,"steps":["Blanda vatten och socker ordentligt","Koka upp och pensla ner kanterna med vatten hela tiden.","Häll därefter i glukossirap och låt koka upp (skumma av).","Låt svalna, använd/kyl."]}],"notes":[]},{"id":"3a8e56f597228071b654ddb7f5ce4d81","notion":"https://app.notion.com/p/3a8e56f597228071b654ddb7f5ce4d81","title":"Blåbärssorbet","intro":"","plan":"","groups":[{"name":"Sockerlag","items":[["66g","vatten"],["90g","socker"],["16g","glukossirap"]]},{"name":"Blåbärspuré","items":[["500g","blåbär (till 300g blåbärspuré)"],["33g","socker"],["33g","vatten"],["","Citronsaft"]]}],"method":[{"name":"Steg 1 – Sockerlag","steps":["Se metod i sidan nedan:"]},{"name":"Steg 2 – Puré","steps":["Väg upp blåbären i vitamixen. Häll i sockret och vattnet. Mixa fint, ca 1 min.","Sila genom chinois.","Blanda med rätt mängd sockerlag, 172g. Antingen med visp eller med stavmixer.","Smaka av med citronsaft."]},{"name":"Steg 3 – Churn","steps":["Häll i blandningen i glassmaskinen.","Gör till “Sorbet” någon av konsistenserna. Tog 40-50 min första gången.","Färdig att äta. Eller stjälp ner i behållare och in i frysen och ta fram när som."]}],"notes":[{"heading":"Sockerlag","lines":["Blir 172g sockerlag."]}]},{"id":"2bbe56f5972280ecb19ce8191e334428","notion":"https://app.notion.com/p/2bbe56f5972280ecb19ce8191e334428","title":"Karamellsås","intro":"Enkel karamellsås som använder den sötade kondenserade mjölken som blir över när du gör No Churn glass.","plan":"","groups":[{"name":null,"items":[["1/2 dl","sötad kondenserad mjölk"],["2msk","smör"],["2-3msk","socker"],["1 nypa","flingsalt (smaka av)"],["1-2msk","vatten/grädde (häll i efter konsistens mot slutet)"]]}],"method":[{"name":null,"steps":["Smält smöret i en kastrull.","Tillsätt strösocker och låt smälta tills gyllene. Använd visp under tiden för att få fin konsistens.","Sänk värmen och rör i kondenserad mjölk.","Vispa och känn efter konsistens, justera med gärdde/vatten.","Smaka av med flingsalt (kylning dämpar sältan, så ta i lite).","Håller sig i kylen i ca 1 vecka. Kan värmas lätt i micro för att få mjukare."]}],"notes":[]},{"id":"3dbe56f5972280f0bfb6cc5dab9032c5","notion":"https://app.notion.com/p/3dbe56f5972280f0bfb6cc5dab9032c5","title":"Chokladsås","intro":"Saltig chokladsås med rom, från Lars.","plan":"10 min.","groups":[{"name":null,"items":[["","Grädde"],["","Kakao"],["","Muscovadosocker"],["","Honung"],["","Salt"],["","Mörk rom"]]}],"method":[{"name":null,"steps":["Blanda allt på medelvärme tills balanserat och det gått ihop sig."]}],"notes":[]},{"id":"360e56f59722808b9f30cc3f993b197c","notion":"https://app.notion.com/p/360e56f59722808b9f30cc3f993b197c","title":"Kladdkaka High","intro":"Källa: Camilla Hamid mykitchenstories.se","plan":"","groups":[{"name":"Steg 1","items":[["225 g","smör"],["3 dl / 260 g","strösocker"],["2 dl / 180 g","brunt farinsocker eller muscovadosocker"]]},{"name":"Steg 2","items":[["3,5 dl / 210 g","vetemjöl"],["1 dl / 40 g","kakao"],["1 krm / 1 g","salt"]]},{"name":"Steg 3","items":[["4 st / ca 220 g","ägg (stora)"]]}],"method":[{"name":"Steg 1","steps":["Sätt ugnen på 175 °C (vanlig). Smörj formen med smör och ströbröd","Smält smöret i en kastrull på medelvärme.","Rör ihop smöret med allt socker så det går ihop sig."]},{"name":"Steg 2","steps":["Blanda resten av de torra ingredienserna i en bunke. Sila gärna för att få en fin blandning. Häll på sockret och smöret utan att blanda."]},{"name":"Steg 3","steps":["Sist i med äggen och blanda allt – rör bara precis tills smeten går ihop."]},{"name":"Gräddning","steps":["Häll smeten i formen och grädda i mitten av ugnen i 25–30 minuter, tills kanterna är fasta och mitten fortfarande är lite vobblig (rörlig).","Låt svalna och ställ sedan in kakan i kylen i minst 4 timmar, gärna över natten – det är då den får sin perfekta kladdighet. Klar."]}],"notes":[{"heading":null,"lines":["All time favorite, sedan Maj 2026."]}]},{"id":"2e1e56f5972280b5bc8af155861be053","notion":"https://app.notion.com/p/2e1e56f5972280b5bc8af155861be053","title":"Lemon Bars","intro":"","plan":"","groups":[{"name":"Crust","items":[["300g","vanligt vetemjöl"],["66g","florsocker"],["1/2tsk","salt"],["170g","smält smör"]]},{"name":"Filling","items":[["3st","citroner för zest"],["600g","socker"],["60g","vanligt vetemjöl"],["8st","L ägg"],["1-2dl","citron beroende på hur söt/sur de önskas (första gången blev 1dl lagom)."]]}],"method":[{"name":null,"steps":["Sätt ugnen på 175 C.","Förbered en jättestor form 22x33 cm ungefär, eller två mindre formar. Antingen som pajformar, annars får du ta bakplåtspapper och klippa så det passar ner i.","Blanda 300g vetemjöl, florsockret och salt ordentligt med köksassistenten med mördegsvisparna.","Häll sist i det smälta smöret och blanda så det är jämnt fördelat.","Ner med degen i formarna och tryck till allt så det blir en jämn botten.","Sätt in i ugnen i 15-20 min (tills ytan blivit något gyllene, inte så viktigt).","Medan den bakas ska du helst hinna göra färdigt fyllningen.","Zesta citronerna och lägg detta ihop med sockret i matberedarens stora behållare och kör tills allt blivit fint blandat.","Häll detta sedan i köksassistentens vispskål du använde tidigare och återanvänd mördegsvisparna här med. Häll i 60g vetemjöl. Kör tills allt är blandat.","Addera sist citronjuicen och alla ägg, blanda tills det är ordentligt blandat men ej blivit vispat och fått luft i sig.","Ta då ut formarna från ugnen när tiden gått och häll över fyllningen.","Sätt in igen på samma temp 175 C, och låt stå i 25 min. (Kanske 22min räcker).","Ta sedan ut och låt svalna en timme och ställ in i kylen (eller direkt ut när det är kallt ute). Ska gärna stå i kylskåpstemp minst 2h.","Kan pudra florsocker ovanpå (men behövdes inte första gången tycker jag).","Servera."]}],"notes":[]},{"id":"330e56f59722804d861ee477d4d87d57","notion":"https://app.notion.com/p/330e56f59722804d861ee477d4d87d57","title":"Chokladpudding","intro":"","plan":"","groups":[{"name":null,"items":[["5 dl","mjölk"],["1 dl","strösocker"],["1","ägg"],["3 msk","majsstärkelse"],["2 msk","kakao"],["1 tsk","vaniljsocker"],["150 g","mörk choklad, finhackad"],["1 msk","smör, rumsvarmt"],["","Nypa salt (smaka av)"]]}],"method":[{"name":null,"steps":["Vispa samman mjölk, socker, ägg, majsstärkelse, kakao och vaniljsocker i en kastrull.","Koka upp under omrörning och sjud 2–3 minuter tills det är en kräm.","Dra av från plattan och rör i chokladen och smöret tills allt smält och du har en len kräm.","Häll upp i portionsformar eller glas och plasta direkt mot ytan så det inte bildas skinn.","Ställ i kylen ca 1 timme tills puddingen är kall.","Servera med vispad grädde och ett bär eller två."]}],"notes":[]},{"id":"331e56f597228094b876e893cea3eb86","notion":"https://app.notion.com/p/331e56f597228094b876e893cea3eb86","title":"Leche Flan","intro":"Filippinsk karamellpudding av Vanjo Merano (Panlasang Pinoy). Enkel och klassisk variant av denna populära dessert.","plan":"","groups":[{"name":null,"items":[["10","äggulor"],["1 burk","kondenserad mjölk (ca 400 g)"],["2,5 dl","färsk mjölk eller evaporerad mjölk"],["2,5 dl","strösocker"],["1 tsk","vaniljextrakt"]]}],"method":[{"name":null,"steps":["Separera äggulorna från vitorna — bara gulorna används. Vispa dem lätt med en gaffel eller elvisp.","Tillsätt kondenserad mjölk och rör om ordentligt. Häll i mjölken och vaniljen och blanda väl.","Värm formen (llanera eller rund kakform) på låg värme på spisen. Häll i sockret och rör tills det smälter till en ljusbrun karamell.","Fördela karamellen jämnt i botten av formen. Låt svalna i 5 minuter.","Häll ägg- och mjölkblandningen i formen och täck tätt med aluminiumfolie.","Ånga formen i 30–35 minuter. Låt svalna i rumstemperatur och ställ sedan in i kylskåp.","Servera kall som dessert."]}],"notes":[]},{"id":"333e56f597228035bb25c2c67c455db9","notion":"https://app.notion.com/p/333e56f597228035bb25c2c67c455db9","title":"Knäckig blåbärspaj","intro":"Saftig blåbärsfyllning under en knäckig, lätt seg smuldeg med havregryn. Camilla Hamid.","plan":"","groups":[{"name":"Fyllning","items":[["250 g","blåbär, färska eller frysta"],["0,25 dl","syltsocker"],["1–1,5 tsk","potatismjöl (alt. majsstärkelse)"]]},{"name":"Knäckig smuldeg","items":[["90 g","smör"],["1 dl","strösocker"],["1 krm","salt"],["1,5 dl","havregryn"],["0,75 dl","vetemjöl"],["0,5 tsk","bakpulver"],["0,25 dl","ljus sirap"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 175 °C (över- och undervärme).","Blanda blåbär, syltsocker och potatismjöl i en bunke och häll ner i pajformen.","Blanda strösocker, salt, havregryn, vetemjöl och bakpulver i en annan bunke.","Smält smöret och rör ner det tillsammans med sirapen i den torra blandningen. Rör ihop till en jämn smet.","Klicka ut smeten över bärfyllningen och bre försiktigt ut den i ett jämnt lager.","Grädda i mitten av ugnen i 30–40 minuter tills pajen fått fin färg.","Servera varm eller rumstempererad, gärna med vaniljglass eller vaniljsås."]}],"notes":[]},{"id":"330e56f5972280eeb492c504b063e25c","notion":"https://app.notion.com/p/330e56f5972280eeb492c504b063e25c","title":"Frasvåfflor","intro":"Klassiska frasvåfflor av Hilda Kirkhoff. Smeten sväller i kylen – gärna över natten.","plan":"","groups":[{"name":null,"items":[["100 g","smör, smält"],["2,5 dl","vatten, kallt"],["2 dl","mjölk"],["3,5 dl","vetemjöl"],["1,5 tsk","bakpulver"],["0,25 dl","strösocker"],["0,5 tsk","salt"]]},{"name":"Smaksättning","items":[["0,5 tsk","malen kardemumma"],["0,5","citron, skalet"],["0,5 tsk","vaniljsocker"]]}],"method":[{"name":null,"steps":["Smält smöret och låt det svalna.","Mät upp övriga ingredienser i en skål och rör om till en klumpfri smet.","Tillsätt smöret och rör om lite till.","Smaksätt med kardemumma, citronskal eller vaniljsocker om du vill.","Ställ smeten i kylen för att svälla, gärna över natten.","Värm upp järnet och grädda smeten till gyllene våfflor."]}],"notes":[]},{"id":"3bde56f5972280a88915cf431681866d","notion":"https://app.notion.com/p/3bde56f5972280a88915cf431681866d","title":"Blondies med körsbär/hallon","intro":"Recept av Emma Brink Rask (Brinken Bakar) — sötsega blondies utan vit choklad. Ger 9 rejäla bitar.","plan":"","groups":[{"name":null,"items":[["110 g","smör"],["120 g","ljus muscovadosocker"],["90 g","strösocker"],["2 tsk","vaniljpulver (eller 3 tsk vaniljsocker)"],["1","ägg"],["0,25 tsk","salt"],["","(75g vit choklad)"],["120 g","vetemjöl"],["150 g","halverade och urkärnade körsbär alternativt hallon"]]}],"method":[{"name":null,"steps":["Värm ugnen till 175 °C vanlig och ta fram eva trio ugnsformen (cirka 20x20)","Smält smöret och låt det svalna något.","Rör ihop båda sockersorterna, vaniljen, ägget och saltet och tillsätt sedan det smälta smöret.","Rör ner mjölet och vänd till sist ner (chokladen och) körsbär/hallon. Spara några till toppen.","Bred ut smeten i formen och strö över resterande körsbär/hallon.","Grädda 20–25 minuter tills kakan fått lite färg och börjar släppa från kanterna. Grädda inte för länge — mitten ska förbli lite kladdig."]}],"notes":[]},{"id":"3cce56f5972280ec9653e2d1aa04be37","notion":"https://app.notion.com/p/3cce56f5972280ec9653e2d1aa04be37","title":"Mugcake Chocochock","intro":"Chokladkaka som görs i en mugg i mikron på ett kvart, av Constance Loeper.","plan":"","groups":[{"name":null,"items":[["3 msk","smör"],["3 msk","vetemjöl"],["3 msk","strösocker"],["2 msk","kakao"],["1 tsk","vaniljsocker"],["3 msk","standardmjölk"]]},{"name":"Topping","items":[["1½ dl","vispgrädde"],["1 dl","hallon, färska eller frysta"]]}],"method":[{"name":null,"steps":["Lägg smöret i en glasmugg och smält det i mikron ca 30 sekunder.","Rör ner mjöl, socker, kakao, vaniljsocker och mjölk till en slät smet. Flytta över hälften av smeten till en likadan mugg.","Kör i mikron 40s. Ytan ska ha stelnat medan mitten är kvar mjuk och kladdig — kakan efterstelnar utanför micron, så ta hellre ut den för lös än för fast.","Vispa grädden och servera till, garnera med hallon."]}],"notes":[{"heading":null,"lines":["Denna blev najs! (Notions nu) (Men skar sig lite tyckte Tilda). Körde 4msk ist för 3msk på allt. 45s blev bra men kan testa 40s nästa gång.","https://www.arla.se/recept/chocochock-muggkaka/"]}]},{"id":"3dce56f59722801f838eeee8fc3c2538","notion":"https://app.notion.com/p/3dce56f59722801f838eeee8fc3c2538","title":"Morotskaka","intro":"Saftig klassisk morotskaka med färskostfrosting, av Roy Fares. Ger ca 10 bitar.","plan":"","groups":[{"name":"Morotskaka","items":[["170 g","finrivna morötter (ca 3 st)"],["150 g","vetemjöl (2,5 dl)"],["2,5 g","bikarbonat (0,5 tsk)"],["3,5 g","bakpulver (0,75 tsk)"],["2 g","salt (0,25 tsk)"],["3 g","malen kanel (1,25 tsk)"],["110 g","ägg (2 st)"],["150 g","strösocker (1,75 dl)"],["130 g","olja (1,5 dl)"]]},{"name":"Frosting","items":[["100 g","osaltat smör, rumsvarmt"],["200 g","färskost (philadelphia)(cream cheese), rumsvarm"],["105 g","florsocker (1,75 dl)"],["6 g","vaniljsocker (1 tsk)"]]}],"method":[{"name":"Morotskaka","steps":["Sätt ugnen på 180 grader. Smörj och mjöla en form på 26 x 19 cm (minsta eva trio långpannan), eller klä botten med bakplåtspapper.","Sikta mjöl, bikarbonat, bakpulver, salt och kanel i en bunke.","Vispa ägg och socker vitt och fluffigt med elvisp i minst 5 minuter. Blanda i oljan och de torra ingredienserna, och rör sist ner morötterna.","Bred ut smeten jämnt i formen och grädda mitt i ugnen i 30–35 minuter. Kontrollera med en sticka att kakan är genomgräddad och låt den svalna helt i formen."]},{"name":"Frosting","steps":["Vispa smör och färskost vitt och fluffigt med elvisp.","Tillsätt florsocker och vaniljsocker och vispa till en fast frosting. Bred frostingen över den kalla kakan."]}],"notes":[]},{"id":"3d1e56f5972280f59342c30c7ca63d8e","notion":"https://app.notion.com/p/3d1e56f5972280f59342c30c7ca63d8e","title":"GULDRUGBRØDET","intro":"","plan":"","groups":[],"method":[],"notes":[{"heading":"Steg 1","lines":["Rör ihop nedanstående","200g surdeg","660g vatten 25-30°C","20g oraffinerat havssalt","Blanda därefter med nedan","130g vetemjöl","260g finmalet rågmjöl","200g havrekli","Låt fermentera med lock i rumstemp i 8-10h."]},{"heading":"Steg 2","lines":["(Ta 200g surdeg från smeten)","Blanda tidigare med det nedan","330ml mellanmörk öl, eriksberg karaktär (lr liknande)","12g honung","130g pumpakärnor/pumpafrön","200g linfrön","200g solrosfrön","Låt fermentera med lock i rumstemp i 5h.","Därefter häller du allt i en form och låt fermentera i 3h till."]},{"heading":"Bakning","lines":["Ställ in i kall ugn och sätt på 200° i 80-85 min.","Eller längre i stor form ca 1h och 50min.","Innertemp ska vara 96-99°.","När de tas ut ur ugnen så rulla in dem i fuktig/blöt kökshandduk för att få ytan mjukare. Låt stå i detta tills de är svala."]},{"heading":"SOURCE:","lines":["Steg 1","Rör ihop nedanstående","•\t300g surdeg","•\t1000g vatten 25-30°C","•\t30-35g oraffinerat havssalt","Blanda därefter med nedan","•\t200g vetemjöl","•\t400g finmalet rågmjöl","•\t300g havrekli","Låt fermentera med lock i rumstemp i 8-10h.","Steg 2","Ta 300g surdeg från smeten","Blanda tidigare med det nedan","•\t500ml mellanmörk öl, eriksberg karaktär (lr liknande)","•\t20g honung","•\t200g pumpakärnor/pumpafrön","•\t300g linfrön","•\t300g solrosfrön","Låt fermentera med lock i rumstemp i 5h.","Därefter häller du allt i en form och låt fermentera i 3h till.","Bakning","Ställ in i kall ugn och sätt på 200° i 80-85 min. Eller längre i stor form, innertemp ska vara 96-99°.","När de tas ut ur ugnen så rulla in dem i fuktig/blöt kökshandduk för att få ytan mjukare. Låt stå i detta tills de är svala."]}]},{"id":"360e56f597228088b063dd3c19dc105e","notion":"https://app.notion.com/p/360e56f597228088b063dd3c19dc105e","title":"Farro Porridge Loaf","intro":"","plan":"","groups":[],"method":[],"notes":[{"heading":null,"lines":["160g HE vetemjöl","160g mediumstarkt vetemjöl","50g starter","240g-270g vatten","8g salt","160g lagad emmer-gröt (farro-gröt)","(emmer-flingor)","Gröten ska gå 15 min efter den kokat upp."]}]},{"id":"360e56f597228035b250db340bd332ea","notion":"https://app.notion.com/p/360e56f597228035b250db340bd332ea","title":"Double-Fermented Pumpernickel","intro":"","plan":"","groups":[],"method":[],"notes":[{"heading":null,"lines":["160g HE vetemjöl","160g mediumstarkt vetemjöl","16g (blackstrap molasses) malted barley sirup","50g starter","240-270g vatten","8g salt","160g cracked rye berries fermented overnight, or up to 3 days","Rye bran for coating"]}]},{"id":"3a8e56f5972280628260c8d26c4c6699","notion":"https://app.notion.com/p/3a8e56f5972280628260c8d26c4c6699","title":"Bananbröd","intro":"Ett saftigt bananbröd – mer kaka än bröd. Servera i skivor med jordnötssmör och lite havssalt. Ica recept.","plan":"","groups":[{"name":null,"items":[["","Smör och mjöl till formen"],["5","mogna bananer (ca 750 g)"],["100 g","rumsvarmt smör"],["2 dl","socker"],["2","ägg"],["3 1/2 dl","vetemjöl (ca 210 g)"],["1 tsk","bakpulver"],["1/2 tsk","salt"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 200°C. Smöra och mjöla en brödform på ca 1 1/2 liter. (Eva trio 1,75 avlånga blir bra).","Skala och mosa bananerna. Vispa smör och socker poröst med elvisp.","Vispa först ner äggen i smörsmeten och sedan de mosade bananerna.","Blanda alla torra ingredienser och vänd ner i smeten. Rör till en slät smet.","Häll smeten i formen.","Grädda i mitten av ugnen ca 40–50 minuter tills kakan är gyllene och en sticka kommer ut torr. Låt svalna och skär i skivor."]}],"notes":[{"heading":"Reflektioner","lines":["Första gången gjorde jag med frusna bananbitar (som släppte vätska när de tinade som jag hade med i) och använde matberedare istället för elvisp. Denna blev väldigt kompakt.","Testa nästa gång med elvisp och färska bananer."]}]},{"id":"3d8e56f597228094be93c369781e72cb","notion":"https://app.notion.com/p/3d8e56f597228094be93c369781e72cb","title":"Claus morgenbrød","intro":"Ett kladdigt formbröd med blandade frön, efter en Claus beskrivning. Ingen exakt mjölmängd — styr på konsistensen.","plan":"","groups":[{"name":null,"items":[["5–10 g","jäst"],["1 liter","vätska (vatten)"],["En stor tesked","salt"],["Ca två nävar","frön, 2–3 olika sorter: pumpakärnor, solrosfrön, sesamfrö, linfrö — det du har hemma"],["","Vanligt vetemjöl och ölandsvete i förhållandet ungefär 2 delar vanligt vetemjöl till 1 del ölandsvete (mängd efter konsistens)"]]}],"method":[{"name":null,"steps":["Lös upp jästen i vätskan.","Rör i salt och frön.","Tillsätt mjölet efterhand och rör ihop degen (t.ex. i köksmaskin). Degen ska bli kladdig och inte för torr — sikta på konsistensen snarare än en exakt mjölmängd.","Häll degen direkt i smorda formar.","Låt jäsa i formarna inne i den kalla ugnen.","Sätt ugnen på 180° med ånga (brödprogram om du har det). Tänd ugnen med brödet redan inne.","Grädda i 50 minuter."]}],"notes":[]},{"id":"3dee56f5972280b0a113fd8c94f9ac8e","notion":"https://app.notion.com/p/3dee56f5972280b0a113fd8c94f9ac8e","title":"Flan Parisien","intro":"Fransk vaniljflan med krämig kärna och mörkt karamelliserad yta, efter Ricardos recept men omräknat till gram och med justerat kok och längre vila.","plan":"","groups":[{"name":"Deg","items":[["215 g","vetemjöl"],["170 g","kallt osaltat smör i tärningar"],["12 g","strösocker"],["1 krm","salt"],["1","äggula"],["4 msk","kall mjölk"]]},{"name":"Flan","items":[["750 g","standardmjölk (3 %)"],["250 g","vispgrädde"],["200 g","strösocker"],["1","vaniljstång, kluven och urskrapad"],["50 g","majsstärkelse (maizena)"],["4","äggulor"],["1","ägg"]]}],"method":[{"name":"Deg","steps":["Blanda mjöl, socker och salt. Arbeta in det kalla smöret med fingertopparna eller i matberedare tills bitarna är i ärtstorlek. Tillsätt äggula och mjölk och samla snabbt ihop till en jämn deg — arbeta den inte mer än nödvändigt. Platta till en rund kaka, plasta och låt vila 30 minuter i kylen.","Kavla ut degen och klä en springform på 20 cm med 6 cm hög kant. Tryck fast degen ordentligt mot botten och kanterna. Ställ formen i frysen i minst 15 minuter."]},{"name":"Kräm","steps":["Koka upp mjölk, socker, vaniljstång och vaniljfrön i en kastrull. Ta av från värmen, lägg på lock och låt dra i 10 minuter.","Vispa under tiden ut majsstärkelsen i den kalla grädden tills den är helt slät. Vispa ner äggulorna, ägget och saltet.","Häll den varma mjölken i en tunn stråle över äggblandningen under vispning. Häll tillbaka allt i kastrullen och koka på medelvärme under ständig omrörning med slickepott, och skrapa botten hela tiden. När krämen tjocknat ska den koka på riktigt med stora bubblor — håll den kokande i 2 minuter så att stärkelsen tillagas helt.","Sila krämen, täck den med plastfolie direkt mot ytan och kyl den helt kall, cirka 1 timme i kylen eller snabbare över isbad."]},{"name":"Gräddning och vila","steps":["Sätt ugnen på 200 °C med gallret i nedersta läget. Rör krämen slät och häll den i det frusna degskalet. Skär bort deg som sticker upp mer än en halv centimeter över krämen.","Grädda i nedersta delen av ugnen 40–45 minuter, tills ytan är fast och bara mitten darrar lätt.","Slå på grillelementet och grilla 3–5 minuter tills ytan är fläckvis mörkt karamelliserad, nästan bränd. Lämna den inte utan uppsikt.","Låt svalna i rumstemperatur och ställ sedan i kylen över natten, minst 8 timmar. Lossa ringen först när flanen är helt kall.","Ta ut flanen ur kylen 30–45 minuter före servering. Den ska ätas sval, inte kylskåpskall."]}],"notes":[]},{"id":"3fce56f59722811aa1e2e74d87fbf06f","notion":"https://app.notion.com/p/3fce56f59722811aa1e2e74d87fbf06f","title":"Baguette","intro":"Rustika franska baguetter på en lös och kladdig deg, från ICA. Halverat recept med torrjäst: 2 baguetter.","plan":"10 min (knåda) + 1 h (jäsning) + 5 min (forma) + 30 min (jäsning, ugnen värms) + 15 min (grädda)\nTotal: ca 2 h","groups":[{"name":null,"items":[["3 g","torrjäst (1 tsk)"],["250 g","vatten (2,5 dl)"],["7 g","salt (1¼ tsk)"],["20 g","olivolja (1½ msk)"],["360 g","vetemjöl special (6 dl)"]]}],"method":[{"name":null,"steps":["Blanda torrjästen med 330 g (5½ dl) mjöl i en bunke, spara 30 g (½ dl) till utbakning. Värm vattnet till 42°C och häll i tillsammans med salt och olivolja. Arbeta degen kraftigt, cirka 10 minuter. Den ska vara lös och kladdig.","Låt degen jäsa under bakduk, cirka 1 timme.","Häll ut degen på mjölad bänk utan att knåda den. Dela i 2 delar, forma avlånga baguetter och vrid dem. Lägg dem på en plåt med bakplåtspapper och pudra över lite mjöl.","Låt bröden jäsa under bakduk, cirka 30 minuter. Sätt under tiden ugnen på 250°C.","Ställ en ugnsform med ca 100 g (1 dl) vatten i botten av ugnen. Grädda bröden mitt i ugnen, cirka 15 minuter.","Låt baguetterna svalna på galler utan duk."]}],"notes":[]},{"id":"403e56f597228183a222cc40bd52ab06","notion":"https://app.notion.com/p/403e56f597228183a222cc40bd52ab06","title":"Knäckig äppelpaj","intro":"Camilla Hamids äppelpaj med kolaäpplen under ett knäckigt havresmul. 6–8 portioner, pajform 20–23 cm.","plan":"15 min (äpplen och fyllning, ugnen värms) + 5 min (smuldeg) + 35 min (grädda)\nTotal: ca 1 h","groups":[{"name":"Fyllning","items":[["ca 900 g","äpplen (8 små eller 4 stora)"],["65 g","strösocker (0,75 dl)"],["20 g","farinsocker (2 msk)"],["8 g","malen kanel (3 tsk)"],["4 g","malen kardemumma (2 tsk)"],["45 g","potatismjöl eller majsstärkelse (4 msk)"]]},{"name":"Smuldeg","items":[["175 g","smör"],["170 g","strösocker (2 dl)"],["2 g","salt (2 krm)"],["105 g","havregryn (3 dl)"],["90 g","vetemjöl (1,5 dl)"],["4 g","bakpulver (1 tsk)"],["8 g","vaniljsocker (2 tsk)"],["70 g","ljus sirap (0,5 dl)"]]}],"method":[{"name":null,"steps":["Sätt ugnen på 175 °C (över- och undervärme). Skala, kärna ur och skär äpplena i bitar, cirka 10 minuter.","Blanda äpplena med strösocker, farinsocker, kanel, kardemumma och potatismjöl. Bred ut i pajformen.","Blanda strösocker, salt, havregryn, vetemjöl, bakpulver och vaniljsocker i en annan bunke.","Smält smöret och häll ner det i bunken tillsammans med sirapen. Rör till en jämn smet, cirka 5 minuter.","Klicka ut smeten över äpplena och bred försiktigt ut den i ett jämnt lager.","Grädda mitt i ugnen tills pajen är gyllenbrun och ytan inte längre är glansig, cirka 30–40 minuter."]}],"notes":[]},{"id":"2e1e56f59722809e956fe62d9f8762f6","notion":"https://app.notion.com/p/2e1e56f59722809e956fe62d9f8762f6","title":"Blåbärspaj V1","intro":"Fastnar i formen, svårjobbad. God, men inte helt det jag är ute efter. Kombo mellan svensk och amerikansk, men brister i helheten.","plan":"","groups":[{"name":"Pajdeg","items":[["2,5dl","vanligt vetemjöl"],["0,75dl","strösocker"],["0,5tsk","bakpulver"],["150g","smör"],["2msk","kallt vatten"],["0,5tsk","salt"]]},{"name":"Fyllning","items":[["225g","svenska blåbär (färska eller frysta)"],["0,5dl","strösocker"],["4tsk","potatismjöl"],["1tsk","salt"]]}],"method":[{"name":null,"steps":["Blanda vetemjöl, strösocker, bakpulver i köksassistenten med mördegsvispar.","Skär smöret i små kuber och lägg i bunken, och häll i vattnet.","Blanda hastigt och inte för mycket, men ska ändå gå ihop något till en smulig deg.","Ställ sedan bunken i kyl 15 min eller frys 5 min (eller motsvarande ute om det är kallt).","(Ta under tiden fram blåbären om de är frysta och se till att de får tina och att eventuell is kan rinna av så att det inte späder ut smaken).","Sätt ugnen på 175 C.","Ta en pajform på 18-20cm och tryck ut halva degen i botten och upp på kanterna.","Grädda pajbotten i mitten av ugnen i 10 min.","Förbered under tiden fyllningen.","Blanda blåbären med sockret, potatismjölet och saltet i en kastrull och få upp temperaturen så sockret smälter och blandningen går ihop sig något.","Den andra halvan av degen ska nu tryckas eller kavlas ut till ett lock. Kan göras med en kavel rakt på bänkskivan om du jobbar snabbt och make it work med degskrapan när det ska läggas över. Annars kan man kavla mellan två bakplåtspapper för att öka chansen att det blir fint.","Skär några snitt i locket så att ångan kan dunsta i ugnen.","Grädda pajen i mitten av ugnen på samma temp 175 C, i 30-40 min. Tills den fått fin gyllene färg.","Servera med vaniljsås, vispad grädde eller vaniljglass."]}],"notes":[{"heading":null,"lines":["Vaniljsås till servering."]}]}];
